rows=[json.loads(l) for l in open(sys.argv[1],encoding='utf-8')]
out=[]
for r in rows:
    t=r.get('type'); ts=r.get('timestamp','')[:19]
    m=r.get('message') or {}
    c=m.get('content')
    if t=='user':
        if isinstance(c,str): out.append(f"{ts} USER: {c[:600]}")
        elif isinstance(c,list):
            for b in c:
                if b.get('type')=='text': out.append(f"{ts} USER: {b['text'][:600]}")
