rows=[json.loads(l) for l in open(sys.argv[1],encoding='utf-8')]
out=[]
for r in rows:
    t=r.get('type'); ts=r.get('timestamp','')[:16]
    if ts < '2026-10-15T21:55': continue
    m=r.get('message') or {}; c=m.get('content')
    if t=='user':
        if isinstance(c,str): out.append(f"{ts} USER: {c[:500]}")
        elif isinstance(c,list): out+= [f"{ts} USER: {b['text'][:500]}" for b in c if b.get('type')=='text']
    elif t=='assistant' and isinstance(c,list):
        for b in c:
            if b.get('type')=='text' and b['text'].strip(): out.append(f"{ts} ASSIST: {b['text'][:3000]}")
            elif b.get('type')=='tool_use': out.append(f"{ts} TOOL {b['name']}: {json.dumps(b.get('input'),ensure_ascii=False)[:400]}")
for l in out: print(l)
EOF
wc -l "$SP/alpha_tail.txt"

