2	import type { CitySuggestion, PlaceDetails, PlacePhoto, PlacesProvider, PlaceSuggestion } from './provider';
3	import { isSelectablePlace } from '/imports/domain/placeSelection';
4	import { fetchWithRetry } from '../fetchRetry';
5	
6	/**
7	 * Google Places API (New). Only active when GOOGLE_PLACES_KEY is set.
8	 * The server key never reaches the browser. The app stores only metadata
9	 * returned by Place Details. Place photos are fetched on demand on the server
10	 * and returned as short-lived URLs; the API key never reaches the browser.
11	 */
12	
13	const BASE = 'https://places.googleapis.com/v1';
14	/** Autocomplete and map lookups have a person waiting: one retry, inside the one timeout. */
15	const interactiveRetry = () => {
16	  const timeoutMs = setting<number>('PLACES_REQUEST_TIMEOUT_MS');
17	  return { timeoutMs, retries: 1, totalMs: timeoutMs };
18	};
19	/** Details also feed background generation, where a second full attempt is affordable. */
20	const detailsRetry = () => {
21	  const timeoutMs = setting<number>('PLACES_REQUEST_TIMEOUT_MS');
22	  return { timeoutMs, totalMs: timeoutMs * 2 };
23	};
24	/** Wide enough for a metropolitan area; autocomplete only prefers it, never restricts to it. */
25	const SEARCH_BIAS_RADIUS_M = 30_000;
26	
27	
28	function key(): string {
29	  const k = process.env.GOOGLE_PLACES_KEY;
30	  if (!k) throw new Error('GOOGLE_PLACES_KEY is not set');
31	  return k;
32	}
33	
34	async function post(path: string, body: unknown, fieldMask: string) {
35	  const res = await fetchWithRetry(`${BASE}${path}`, {
36	    method: 'POST',
37	    headers: {
38	      'Content-Type': 'application/json',
39	      'X-Goog-Api-Key': key(),
40	      'X-Goog-FieldMask': fieldMask,
41	    },
42	    body: JSON.stringify(body),
43	  }, interactiveRetry());
44	  if (!res.ok) throw new Error(`Places ${path} failed: ${res.status}`);
45	  return res.json() as Promise<any>;
46	}
47	
48	/**
49	 * Quality 2 — the cheapest signal there is, and no AI involved.
50	 *
51	 * If a place in Hanoi has 90% of its reviews in English it is a tourist trap
52	 * whatever the rating says; if Vietnamese dominates, locals go there.
53	 * Turned off in English-speaking cities, where the test means nothing.
54	 */
55	export const googlePlacesProvider: PlacesProvider = {
56	  kind: 'google',
57	
58	  async cityNear(lat, lng) {
59	    // Nearby place address components avoid requiring a separate Geocoding API.
60	    const data = await post('/places:searchNearby', {
61	      locationRestriction: { circle: { center: { latitude: lat, longitude: lng }, radius: 10000 } },
62	      rankPreference: 'DISTANCE', maxResultCount: 3, languageCode: 'en',
63	    }, 'places.addressComponents');
64	    for (const place of data.places ?? []) {
65	      const components: { longText: string; types: string[] }[] = place.addressComponents ?? [];
66	      const city = components.find(c => c.types.includes('locality')) ?? components.find(c => c.types.includes('postal_town'));
67	      const country = components.find(c => c.types.includes('country'));
68	      if (!city?.longText) continue;
69	      const matches = await googlePlacesProvider.searchCities([city.longText, country?.longText].filter(Boolean).join(', '));
70	      return matches[0] ?? null;
71	    }
72	    return null;
73	  },
74	
75	  async search(query, opts) {
76	    const data = await post(
77	      '/places:autocomplete',
78	      {
79	        input: query,
80	        sessionToken: opts.sessionToken,
81	        ...(opts.languageCode ? { languageCode: opts.languageCode } : {}),
82	        // Without a bias Google ranks by the server's IP, which is nowhere near the traveller.
83	        ...(opts.near ? { locationBias: { circle: {
84	          center: { latitude: opts.near.lat, longitude: opts.near.lng }, radius: SEARCH_BIAS_RADIUS_M,
85	        } } } : {}),
86	      },
87	      'suggestions.placePrediction.placeId,suggestions.placePrediction.text.text,suggestions.placePrediction.structuredFormat,suggestions.placePrediction.types',
88	    );
89	    const list: any[] = data.suggestions ?? [];
90	    return list
91	      .filter((s) => s.placePrediction && isSelectablePlace(s.placePrediction.types))
92	      .slice(0, 6)
93	      .map((s): PlaceSuggestion => {
94	        const p = s.placePrediction;
95	        const text: string = p.structuredFormat?.mainText?.text ?? p.text?.text ?? '';
96	        const secondary: string = p.structuredFormat?.secondaryText?.text ?? '';
97	
98	        // "Vanich 1 Road, Samphanthawong, Bangkok, Thailand" — the last part is
99	        // the country and the one before it is the city. Taking the last part
100	        // labelled every Bangkok bar as "Thailand".
101	        const parts = secondary
102	          .split(',')
103	          .map((part) => part.trim())
104	          .filter(Boolean);
105	
106	        return {
107	          placeId: p.placeId,
108	          name: text,
109	          city: parts.length > 1 ? parts[parts.length - 2] : (parts[0] ?? ''),
110	          area: parts.length > 2 ? parts[0] : undefined,
111	        };
112	      });
113	  },
114	
115	  async searchCities(query, sessionToken, languageCode): Promise<CitySuggestion[]> {
116	    const data = await post(
117	      '/places:autocomplete',
118	      { input: query, includedPrimaryTypes: ['(cities)'], sessionToken, ...(languageCode ? { languageCode } : {}) },
119	      'suggestions.placePrediction.placeId,suggestions.placePrediction.text.text,suggestions.placePrediction.structuredFormat',
120	    );
121	
122	    return (data.suggestions ?? [])
123	      .filter((s: any) => s.placePrediction)
124	      .slice(0, 6)
125	      .map((s: any): CitySuggestion => {
126	        const p = s.placePrediction;
127	        return {
128	          placeId: p.placeId,
129	          label: p.text?.text ?? '',
130	          city: p.structuredFormat?.mainText?.text ?? p.text?.text ?? '',
131	        };
132	      });
133	  },
134	
135	  async details(placeId, opts = {}) {
136	    const fields = [
137	      'id',
138	      'displayName',
139	      'formattedAddress',
140	      'addressComponents',
141	      'location',
142	      'businessStatus',
143	        'types',
144	        'primaryType',
145	    ].join(',');
146	
147	    const session = opts.sessionToken ? `?sessionToken=${encodeURIComponent(opts.sessionToken)}` : '';
148	    const res = await fetchWithRetry(`${BASE}/places/${encodeURIComponent(placeId)}${session}`, {
149	      headers: { 'X-Goog-Api-Key': key(), 'X-Goog-FieldMask': fields },
150	    }, detailsRetry());
151	    if (!res.ok) {
152	      // Only "this place does not exist" is an answer. A throttled or failing
153	      // Google must surface as an error, not as "no such place".
154	      if (res.status === 400 || res.status === 404) return null;
155	      throw new Error(`Places details failed: ${res.status}`);
156	    }
157	    const d: any = await res.json();
158	
159	    /**
160	     * `locality` is missing in plenty of countries — Bangkok addresses carry
161	     * none at all — so fall through the wider administrative levels instead
162	     * of leaving the city blank.
163	     */
164	    const components: any[] = d.addressComponents ?? [];
165	    const byType = (type: string) => components.find((c: any) => c.types?.includes(type));
166	    const cityComponent =
167	      byType('locality') ??
168	      byType('postal_town') ??
169	      byType('administrative_area_level_2') ??
170	      byType('administrative_area_level_1');
171	    const areaComponent = components.find((c: any) =>
172	      c.types?.some((t: string) => t.startsWith('sublocality')),
173	    );
174	
175	    const place: PlaceDetails = {
176	      placeId: d.id,
177	      name: d.displayName?.text ?? '',
178	      city: cityComponent?.longText ?? '',
179	      country: byType('country')?.longText,
180	      countryCode: /^[A-Z]{2}$/i.test(byType('country')?.shortText ?? '')
181	        ? byType('country').shortText.toUpperCase() : undefined,
182	      area: areaComponent?.longText,
183	      lat: d.location?.latitude ?? 0,
184	      lng: d.location?.longitude ?? 0,
185	      businessStatus: d.businessStatus,
186	      types: d.types ?? [],
187	      primaryType: d.primaryType ?? null,
188	      tags: [], // filled in by the LLM enricher
189	      popularityScore: 0.5,
190	      source: 'google',
191	      verifiedAt: new Date(),
192	      // `priceLevel` and opening hours are Enterprise fields. Reviews/photos
193	      // are Atmosphere. Keep ordinary verification at the Pro tier; richer
194	      // facts can be fetched deliberately for a final card later.
195	    };
196	    return place;
197	  },
198	
199	  async photo(placeId): Promise<PlacePhoto | null> {
200	    // Photo resource names expire and Google does not permit caching them, so
201	    // retrieve one only when a card needs to paint it.
202	    const placeRes = await fetch(`${BASE}/places/${encodeURIComponent(placeId)}`, {
203	      headers: { 'X-Goog-Api-Key': key(), 'X-Goog-FieldMask': 'photos' },
204	      signal: AbortSignal.timeout(setting('PLACES_REQUEST_TIMEOUT_MS')),
205	    });
206	    if (!placeRes.ok) return null;
207	    const photo = (await placeRes.json() as any).photos?.[0];
208	    if (!photo?.name || typeof photo.name !== 'string') return null;
209	
210	    const resource = photo.name.split('/').map(encodeURIComponent).join('/');
211	    const media = await fetch(
212	      `${BASE}/${resource}/media?key=${encodeURIComponent(key())}&maxWidthPx=400&maxHeightPx=400&skipHttpRedirect=true`,
213	      { signal: AbortSignal.timeout(setting('PLACES_REQUEST_TIMEOUT_MS')) },
214	    );
215	    if (!media.ok) return null;
216	    const data: any = await media.json();
217	    if (!data.photoUri || typeof data.photoUri !== 'string') return null;
218	
219	    const attribution = (photo.authorAttributions ?? [])
220	      .map((author: any) => author.displayName)
221	      .filter((name: unknown): name is string => typeof name === 'string' && name.length > 0)
222	      .join(', ') || undefined;
223	    return { url: data.photoUri, attribution };
224	  },
225	
226	  async nearby(city) {
227	    const data = await post(
228	      '/places:searchText',
229	      { textQuery: `bars and restaurants in ${city}`, maxResultCount: 10 },
230	      'places.id,places.displayName,places.location',
231	    );
232	    return (data.places ?? []).map(
233	      (p: any): PlaceSuggestion => ({
234	        placeId: p.id,
235	        name: p.displayName?.text ?? '',
236	        city,
237	        lat: p.location?.latitude,
238	        lng: p.location?.longitude,
239	      }),
240	    );
241	  },
242	};
