import { setting } from '/server/runtimeSettings';
import type { CitySuggestion, PlaceDetails, PlacePhoto, PlacesProvider, PlaceSuggestion } from './provider';
import { isSelectablePlace } from '/imports/domain/placeSelection';
import { fetchWithRetry } from '../fetchRetry';

/**
 * Google Places API (New). Only active when GOOGLE_PLACES_KEY is set.
 * The server key never reaches the browser. The app stores only metadata
 * returned by Place Details. Place photos are fetched on demand on the server
 * and returned as short-lived URLs; the API key never reaches the browser.
 */

const BASE = 'https://places.googleapis.com/v1';
/** Autocomplete and map lookups have a person waiting: one retry, inside the one timeout. */
const interactiveRetry = () => {
  const timeoutMs = setting<number>('PLACES_REQUEST_TIMEOUT_MS');
  return { timeoutMs, retries: 1, totalMs: timeoutMs };
};
/** Details also feed background generation, where a second full attempt is affordable. */
const detailsRetry = () => {
  const timeoutMs = setting<number>('PLACES_REQUEST_TIMEOUT_MS');
  return { timeoutMs, totalMs: timeoutMs * 2 };
};
/** Wide enough for a metropolitan area; autocomplete only prefers it, never restricts to it. */
const SEARCH_BIAS_RADIUS_M = 30_000;


function key(): string {
  const k = process.env.GOOGLE_PLACES_KEY;
  if (!k) throw new Error('GOOGLE_PLACES_KEY is not set');
  return k;
}

async function post(path: string, body: unknown, fieldMask: string) {
  const res = await fetchWithRetry(`${BASE}${path}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Goog-Api-Key': key(),
      'X-Goog-FieldMask': fieldMask,
    },
    body: JSON.stringify(body),
  }, interactiveRetry());
  if (!res.ok) throw new Error(`Places ${path} failed: ${res.status}`);
  return res.json() as Promise<any>;
}

/**
 * Quality 2 — the cheapest signal there is, and no AI involved.
 *
 * If a place in Hanoi has 90% of its reviews in English it is a tourist trap
 * whatever the rating says; if Vietnamese dominates, locals go there.
 * Turned off in English-speaking cities, where the test means nothing.
 */
export const googlePlacesProvider: PlacesProvider = {
  kind: 'google',

  async cityNear(lat, lng) {
    // Nearby place address components avoid requiring a separate Geocoding API.
    const data = await post('/places:searchNearby', {
      locationRestriction: { circle: { center: { latitude: lat, longitude: lng }, radius: 10000 } },
      rankPreference: 'DISTANCE', maxResultCount: 3, languageCode: 'en',
    }, 'places.addressComponents');
    for (const place of data.places ?? []) {
      const components: { longText: string; types: string[] }[] = place.addressComponents ?? [];
      const city = components.find(c => c.types.includes('locality')) ?? components.find(c => c.types.includes('postal_town'));
      const country = components.find(c => c.types.includes('country'));
      if (!city?.longText) continue;
      const matches = await googlePlacesProvider.searchCities([city.longText, country?.longText].filter(Boolean).join(', '));
      return matches[0] ?? null;
    }
    return null;
  },

  async search(query, opts) {
    const data = await post(
      '/places:autocomplete',
      {
        input: query,
        sessionToken: opts.sessionToken,
        ...(opts.languageCode ? { languageCode: opts.languageCode } : {}),
        // Without a bias Google ranks by the server's IP, which is nowhere near the traveller.
        ...(opts.near ? { locationBias: { circle: {
          center: { latitude: opts.near.lat, longitude: opts.near.lng }, radius: SEARCH_BIAS_RADIUS_M,
        } } } : {}),
      },
      'suggestions.placePrediction.placeId,suggestions.placePrediction.text.text,suggestions.placePrediction.structuredFormat,suggestions.placePrediction.types',
    );
    const list: any[] = data.suggestions ?? [];
    return list
      .filter((s) => s.placePrediction && isSelectablePlace(s.placePrediction.types))
      .slice(0, 6)
      .map((s): PlaceSuggestion => {
        const p = s.placePrediction;
        const text: string = p.structuredFormat?.mainText?.text ?? p.text?.text ?? '';
        const secondary: string = p.structuredFormat?.secondaryText?.text ?? '';

        // "Vanich 1 Road, Samphanthawong, Bangkok, Thailand" — the last part is
        // the country and the one before it is the city. Taking the last part
        // labelled every Bangkok bar as "Thailand".
        const parts = secondary
          .split(',')
          .map((part) => part.trim())
          .filter(Boolean);

        return {
          placeId: p.placeId,
          name: text,
          city: parts.length > 1 ? parts[parts.length - 2] : (parts[0] ?? ''),
          area: parts.length > 2 ? parts[0] : undefined,
        };
      });
  },

  async searchCities(query, sessionToken, languageCode): Promise<CitySuggestion[]> {
    const data = await post(
      '/places:autocomplete',
      { input: query, includedPrimaryTypes: ['(cities)'], sessionToken, ...(languageCode ? { languageCode } : {}) },
      'suggestions.placePrediction.placeId,suggestions.placePrediction.text.text,suggestions.placePrediction.structuredFormat',
    );

    return (data.suggestions ?? [])
      .filter((s: any) => s.placePrediction)
      .slice(0, 6)
      .map((s: any): CitySuggestion => {
        const p = s.placePrediction;
        return {
          placeId: p.placeId,
          label: p.text?.text ?? '',
          city: p.structuredFormat?.mainText?.text ?? p.text?.text ?? '',
        };
      });
  },

  async details(placeId, opts = {}) {
    const fields = [
      'id',
      'displayName',
      'formattedAddress',
      'addressComponents',
      'location',
      'businessStatus',
        'types',
        'primaryType',
    ].join(',');

    const session = opts.sessionToken ? `?sessionToken=${encodeURIComponent(opts.sessionToken)}` : '';
    const res = await fetchWithRetry(`${BASE}/places/${encodeURIComponent(placeId)}${session}`, {
      headers: { 'X-Goog-Api-Key': key(), 'X-Goog-FieldMask': fields },
    }, detailsRetry());
    if (!res.ok) {
      // Only "this place does not exist" is an answer. A throttled or failing
      // Google must surface as an error, not as "no such place".
      if (res.status === 400 || res.status === 404) return null;
      throw new Error(`Places details failed: ${res.status}`);
    }
    const d: any = await res.json();

    /**
     * `locality` is missing in plenty of countries — Bangkok addresses carry
     * none at all — so fall through the wider administrative levels instead
     * of leaving the city blank.
     */
    const components: any[] = d.addressComponents ?? [];
    const byType = (type: string) => components.find((c: any) => c.types?.includes(type));
    const cityComponent =
      byType('locality') ??
      byType('postal_town') ??
      byType('administrative_area_level_2') ??
      byType('administrative_area_level_1');
    const areaComponent = components.find((c: any) =>
      c.types?.some((t: string) => t.startsWith('sublocality')),
    );

    const place: PlaceDetails = {
      placeId: d.id,
      name: d.displayName?.text ?? '',
      city: cityComponent?.longText ?? '',
      country: byType('country')?.longText,
      countryCode: /^[A-Z]{2}$/i.test(byType('country')?.shortText ?? '')
        ? byType('country').shortText.toUpperCase() : undefined,
      area: areaComponent?.longText,
      lat: d.location?.latitude ?? 0,
      lng: d.location?.longitude ?? 0,
      businessStatus: d.businessStatus,
      types: d.types ?? [],
      primaryType: d.primaryType ?? null,
      tags: [], // filled in by the LLM enricher
      popularityScore: 0.5,
      source: 'google',
      verifiedAt: new Date(),
      // `priceLevel` and opening hours are Enterprise fields. Reviews/photos
      // are Atmosphere. Keep ordinary verification at the Pro tier; richer
      // facts can be fetched deliberately for a final card later.
    };
    return place;
  },

  async photo(placeId): Promise<PlacePhoto | null> {
    // Photo resource names expire and Google does not permit caching them, so
    // retrieve one only when a card needs to paint it.
    const placeRes = await fetch(`${BASE}/places/${encodeURIComponent(placeId)}`, {
      headers: { 'X-Goog-Api-Key': key(), 'X-Goog-FieldMask': 'photos' },
      signal: AbortSignal.timeout(setting('PLACES_REQUEST_TIMEOUT_MS')),
    });
    if (!placeRes.ok) return null;
    const photo = (await placeRes.json() as any).photos?.[0];
    if (!photo?.name || typeof photo.name !== 'string') return null;

    const resource = photo.name.split('/').map(encodeURIComponent).join('/');
    const media = await fetch(
      `${BASE}/${resource}/media?key=${encodeURIComponent(key())}&maxWidthPx=400&maxHeightPx=400&skipHttpRedirect=true`,
      { signal: AbortSignal.timeout(setting('PLACES_REQUEST_TIMEOUT_MS')) },
    );
    if (!media.ok) return null;
    const data: any = await media.json();
    if (!data.photoUri || typeof data.photoUri !== 'string') return null;

    const attribution = (photo.authorAttributions ?? [])
      .map((author: any) => author.displayName)
      .filter((name: unknown): name is string => typeof name === 'string' && name.length > 0)
      .join(', ') || undefined;
    return { url: data.photoUri, attribution };
  },

  async nearby(city) {
    const data = await post(
      '/places:searchText',
      { textQuery: `bars and restaurants in ${city}`, maxResultCount: 10 },
      'places.id,places.displayName,places.location',
    );
    return (data.places ?? []).map(
      (p: any): PlaceSuggestion => ({
        placeId: p.id,
        name: p.displayName?.text ?? '',
        city,
        lat: p.location?.latitude,
        lng: p.location?.longitude,
      }),
    );
  },
};

