1	import { Meteor } from 'meteor/meteor';
2	
3	/**
4	 * Loader for the Maps JavaScript API.
5	 *
6	 * This key is a browser key by design — it ships to the client and is
7	 * protected by an HTTP-referrer restriction in Google Cloud, not by secrecy.
8	 * It is a different key from GOOGLE_PLACES_KEY, which stays on the server and
9	 * must never reach here.
10	 */
11	
12	let loading: Promise<typeof google.maps> | null = null;
13	
14	export function mapsKey(): string | undefined {
15	  return (Meteor.settings?.public as { mapsKey?: string } | undefined)?.mapsKey || undefined;
16	}
17	
18	export function loadMaps(): Promise<typeof google.maps> {
19	  if (loading) return loading;
20	
21	  const key = mapsKey();
22	  if (!key) return Promise.reject(new Error('mapsKey is not configured'));
23	
24	  loading = new Promise<typeof google.maps>((resolve, reject) => {
25	    // The callback form is the one that guarantees a fully populated
26	    // namespace: with loading=async the script resolves before google.maps
27	    // has its constructors, and google.maps.Map is not there yet.
28	    const done = `__vergerMaps${Date.now()}`;
29	    (window as any)[done] = () => {
30	      delete (window as any)[done];
31	      resolve(google.maps);
32	    };
33	
34	    const script = document.createElement('script');
35	    script.src =
36	      `https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(key)}` +
37	      `&v=weekly&callback=${done}`;
38	    script.async = true;
39	    script.onerror = () => reject(new Error('Maps JavaScript API failed to load'));
40	    document.head.appendChild(script);
41	  });
42	
43	  return loading;
44	}
