import { Meteor } from 'meteor/meteor';

/**
 * Loader for the Maps JavaScript API.
 *
 * This key is a browser key by design — it ships to the client and is
 * protected by an HTTP-referrer restriction in Google Cloud, not by secrecy.
 * It is a different key from GOOGLE_PLACES_KEY, which stays on the server and
 * must never reach here.
 */

let loading: Promise<typeof google.maps> | null = null;

export function mapsKey(): string | undefined {
  return (Meteor.settings?.public as { mapsKey?: string } | undefined)?.mapsKey || undefined;
}

export function loadMaps(): Promise<typeof google.maps> {
  if (loading) return loading;

  const key = mapsKey();
  if (!key) return Promise.reject(new Error('mapsKey is not configured'));

  loading = new Promise<typeof google.maps>((resolve, reject) => {
    // The callback form is the one that guarantees a fully populated
    // namespace: with loading=async the script resolves before google.maps
    // has its constructors, and google.maps.Map is not there yet.
    const done = `__vergerMaps${Date.now()}`;
    (window as any)[done] = () => {
      delete (window as any)[done];
      resolve(google.maps);
    };

    const script = document.createElement('script');
    script.src =
      `https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(key)}` +
      `&v=weekly&callback=${done}`;
    script.async = true;
    script.onerror = () => reject(new Error('Maps JavaScript API failed to load'));
    document.head.appendChild(script);
  });

  return loading;
}

