161	async function candidatesFor(
162	  city: string,
163	  locale?: string,
164	  usage?: UsageSink,
165	  excluded: TripPlace[] = [],
166	  category?: Category,
167	  allowedTypes: VenueType[] = [],
168	  cityPlaceId?: string,
169	  recovery?: { keep: Candidate[]; excludeNames: string[] },
170	): Promise<{ candidates: Candidate[]; fromCache: boolean }> {
171	  // A city search is one combined retrieval for all eligible types. Its pool
172	  // is shared by city and type set; categories never become parallel calls.
173	  const scope = allowedTypes?.length ? [...allowedTypes].sort().join(',') : 'all';
174	  // Existing food/nightlife pools remain reusable; outdoor retrieval has its
175	  // own version so future nature changes cannot invalidate unrelated caches.
176	  const version = allowedTypes.some(type => venueCategory(type) === 'nature') ? 'city-outdoors-v1' : 'city-verified-v3';
177	  const discovery = setting<string>('PROMPT_DISCOVERY');
178	  // Keep existing default pools; custom prompt revisions get a separate cache.
179	  const promptVersion = discovery === DISCOVERY_TEMPLATE ? '' : `:prompt-${createHash('sha256').update(discovery).digest('hex').slice(0, 16)}`;
180	  const cacheKey = `${cityPlaceId ?? city.toLowerCase()}:${version}:${scope}${promptVersion}`;
181	  const cutoff = new Date(Date.now() - CANDIDATES_TTL_DAYS * 86_400_000);
182	  const cached = recovery ? null : await CityCandidatesCollection.findOneAsync({
183	    city: cacheKey,
184	    createdAt: { $gte: cutoff },
185	  });
186	  const excludedNames = [...excluded.map(place => place.name), ...(recovery?.excludeNames ?? [])];
187	  const names = new Set(excludedNames.map(venueKey));
188	  const unseen = (items: Candidate[]) => {
189	    const seen = new Set(names);
190	    return items.filter(item => {
191	      const key = venueKey(item.n);
192	      if (seen.has(key)) return false;
193	      seen.add(key);
194	      return true;
195	    });
196	  };
197	  const minimum = category ? RECOMMENDATION_PAGE_SIZE : INITIAL_RECOMMENDATION_LIMIT;
198	  const cachedCandidates = cached ? unseen(cached.candidates) : [];
199	  if (cachedCandidates.length >= minimum) return { candidates: cachedCandidates, fromCache: true };
200	
201	  let found: Candidate[];
202	  try {
203	    found = await getLLMProvider().findCandidates(city, locale, usage,
204	      category, excludedNames, allowedTypes);
205	  } catch (error) {
206	    // A short existing pool is still usable during a discovery outage. It
207	    // must be verified below, and this run must not retry the failed top-up.
208	    if (cachedCandidates.length) return { candidates: cachedCandidates, fromCache: false };
209	    throw error;
210	  }
211	  const candidates = unseen([...(recovery?.keep ?? cachedCandidates), ...found]);
212	  // Additional batches must not replace the shared discovery pool.
213	  if (excluded.length) return { candidates, fromCache: false };
214	  await CityCandidatesCollection.upsertAsync(
215	    { city: cacheKey },
216	    { $set: { city: cacheKey, candidates, createdAt: new Date() } },
217	  );
218	  return { candidates, fromCache: false };
219	}
