250	/**
251	 * Attach what we already know from Places to each candidate: closing time and
252	 * price register describe the crowd, and a high rating on few reviews is the
253	 * definition of a place someone would not have found alone (quality 6).
254	 */
255	async function withFacts(candidates: Candidate[], city: string, location?: CityLocation): Promise<Candidate[]> {
256	  const known = await PlacesCollection.find({ city }).fetchAsync();
257	  const byName = new Map(known.filter(place => !location || isInCity(place, location)).map((place) => [place.name.toLowerCase(), place]));
258	
259	  return candidates.map((candidate) => {
260	    const place = byName.get(candidate.n.toLowerCase());
261	    if (!place) return candidate;
262	
263	    const facts = [
264	      place.rating ? `рейтинг ${place.rating}` : '',
265	      place.ratingCount ? `${place.ratingCount} отзывов` : '',
266	      place.priceLevel ? `цена ${'₽'.repeat(place.priceLevel)}` : '',
267	      place.closesLate ? 'закрывается поздно' : '',
268	      place.opensEarly ? 'открывается рано' : '',
269	    ]
270	      .filter(Boolean)
271	      .join(', ');
272	
273	    return facts ? { ...candidate, facts } : candidate;
274	  });
275	}
