277	/** Distribute one fixed-size collection over every type the person saved. */
278	function typeTargets(types: VenueType[], anchors: { primaryType?: string | null; types?: string[] }[]) {
279	  const weights = new Map(types.map((type) => [
280	    type,
281	    Math.max(1, anchors.filter((place) => venueTypeOf(place) === type).length),
282	  ]));
283	  const totalWeight = [...weights.values()].reduce((sum, weight) => sum + weight, 0);
284	  const targets = new Map(types.map((type) => [
285	    type,
286	    Math.max(1, Math.floor(INITIAL_RECOMMENDATION_LIMIT * (weights.get(type)! / totalWeight))),
287	  ]));
288	  let assigned = [...targets.values()].reduce((sum, count) => sum + count, 0);
289	  const priority = [...types].sort((a, b) => {
290	    const aRemainder = INITIAL_RECOMMENDATION_LIMIT * (weights.get(a)! / totalWeight) - targets.get(a)!;
291	    const bRemainder = INITIAL_RECOMMENDATION_LIMIT * (weights.get(b)! / totalWeight) - targets.get(b)!;
292	    return bRemainder - aRemainder || (weights.get(b)! - weights.get(a)!);
293	  });
294	  for (let index = 0; assigned < INITIAL_RECOMMENDATION_LIMIT; index += 1, assigned += 1) {
295	    const type = priority[index % priority.length];
296	    targets.set(type, targets.get(type)! + 1);
297	  }
298	  return Object.fromEntries(targets) as Partial<Record<VenueType, number>>;
299	}
