async function candidatesFor(
  city: string,
  locale?: string,
  usage?: UsageSink,
  excluded: TripPlace[] = [],
  category?: Category,
  allowedTypes: VenueType[] = [],
  cityPlaceId?: string,
  recovery?: { keep: Candidate[]; excludeNames: string[] },
): Promise<{ candidates: Candidate[]; fromCache: boolean }> {
  // A city search is one combined retrieval for all eligible types. Its pool
  // is shared by city and type set; categories never become parallel calls.
  const scope = allowedTypes?.length ? [...allowedTypes].sort().join(',') : 'all';
  // Existing food/nightlife pools remain reusable; outdoor retrieval has its
  // own version so future nature changes cannot invalidate unrelated caches.
  const version = allowedTypes.some(type => venueCategory(type) === 'nature') ? 'city-outdoors-v1' : 'city-verified-v3';
  const discovery = setting<string>('PROMPT_DISCOVERY');
  // Keep existing default pools; custom prompt revisions get a separate cache.
  const promptVersion = discovery === DISCOVERY_TEMPLATE ? '' : `:prompt-${createHash('sha256').update(discovery).digest('hex').slice(0, 16)}`;
  const cacheKey = `${cityPlaceId ?? city.toLowerCase()}:${version}:${scope}${promptVersion}`;
  const cutoff = new Date(Date.now() - CANDIDATES_TTL_DAYS * 86_400_000);
  const cached = recovery ? null : await CityCandidatesCollection.findOneAsync({
    city: cacheKey,
    createdAt: { $gte: cutoff },
  });
  const excludedNames = [...excluded.map(place => place.name), ...(recovery?.excludeNames ?? [])];
  const names = new Set(excludedNames.map(venueKey));
  const unseen = (items: Candidate[]) => {
    const seen = new Set(names);
    return items.filter(item => {
      const key = venueKey(item.n);
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  };
  const minimum = category ? RECOMMENDATION_PAGE_SIZE : INITIAL_RECOMMENDATION_LIMIT;
  const cachedCandidates = cached ? unseen(cached.candidates) : [];
  if (cachedCandidates.length >= minimum) return { candidates: cachedCandidates, fromCache: true };

  let found: Candidate[];
  try {
    found = await getLLMProvider().findCandidates(city, locale, usage,
      category, excludedNames, allowedTypes);
  } catch (error) {
    // A short existing pool is still usable during a discovery outage. It
    // must be verified below, and this run must not retry the failed top-up.
    if (cachedCandidates.length) return { candidates: cachedCandidates, fromCache: false };
    throw error;
  }
  const candidates = unseen([...(recovery?.keep ?? cachedCandidates), ...found]);
  // Additional batches must not replace the shared discovery pool.
  if (excluded.length) return { candidates, fromCache: false };
  await CityCandidatesCollection.upsertAsync(
    { city: cacheKey },
    { $set: { city: cacheKey, candidates, createdAt: new Date() } },
  );
  return { candidates, fromCache: false };
}

export const TRIP_TASK = 'trip.generate';

/**
 * Registered once at import: the worker looks up handlers by type, so a task
 * enqueued before a restart is picked up after it.
 */
registerHandler(TRIP_TASK, async (payload: {
  userId: string;
  tripId: string;
  city: string;
  locale?: string;
  near?: { lat: number; lng: number };
}) => {
  try {
    await runGeneration(payload.userId, payload.tripId, payload.city, payload.locale, payload.near);
  } catch (error) {
    logFailure('trip task', payload.tripId, error);
    // Queue failures happen outside the request path. Mark and settle here so
    // an upstream timeout or a bad cached record never holds quota forever.
    const failed = await TripsCollection.updateAsync(
      { _id: payload.tripId, userId: payload.userId, status: 'pending' },
      { $set: { status: 'failed', error: 'Unable to generate this trip. Please try again later.' } },
    );
    if (failed) void trackProductEvent(payload.userId, { name: 'Trip Failed', outOfSession: true });
    await recordFailure(payload.userId, payload.tripId, 'task', error);
    await settleTrip(payload.tripId, payload.userId, [], failed > 0);
  }
});

/**
 * Attach what we already know from Places to each candidate: closing time and
 * price register describe the crowd, and a high rating on few reviews is the
 * definition of a place someone would not have found alone (quality 6).
 */
async function withFacts(candidates: Candidate[], city: string, location?: CityLocation): Promise<Candidate[]> {
  const known = await PlacesCollection.find({ city }).fetchAsync();
  const byName = new Map(known.filter(place => !location || isInCity(place, location)).map((place) => [place.name.toLowerCase(), place]));

  return candidates.map((candidate) => {
    const place = byName.get(candidate.n.toLowerCase());
    if (!place) return candidate;

    const facts = [
      place.rating ? `рейтинг ${place.rating}` : '',
      place.ratingCount ? `${place.ratingCount} отзывов` : '',
      place.priceLevel ? `цена ${'₽'.repeat(place.priceLevel)}` : '',
      place.closesLate ? 'закрывается поздно' : '',
      place.opensEarly ? 'открывается рано' : '',
    ]
      .filter(Boolean)
      .join(', ');

    return facts ? { ...candidate, facts } : candidate;
  });
}

/** Distribute one fixed-size collection over every type the person saved. */
function typeTargets(types: VenueType[], anchors: { primaryType?: string | null; types?: string[] }[]) {
  const weights = new Map(types.map((type) => [
    type,
    Math.max(1, anchors.filter((place) => venueTypeOf(place) === type).length),
  ]));
  const totalWeight = [...weights.values()].reduce((sum, weight) => sum + weight, 0);
  const targets = new Map(types.map((type) => [
    type,
    Math.max(1, Math.floor(INITIAL_RECOMMENDATION_LIMIT * (weights.get(type)! / totalWeight))),
  ]));
  let assigned = [...targets.values()].reduce((sum, count) => sum + count, 0);
  const priority = [...types].sort((a, b) => {
    const aRemainder = INITIAL_RECOMMENDATION_LIMIT * (weights.get(a)! / totalWeight) - targets.get(a)!;
    const bRemainder = INITIAL_RECOMMENDATION_LIMIT * (weights.get(b)! / totalWeight) - targets.get(b)!;
    return bRemainder - aRemainder || (weights.get(b)! - weights.get(a)!);
  });
  for (let index = 0; assigned < INITIAL_RECOMMENDATION_LIMIT; index += 1, assigned += 1) {
    const type = priority[index % priority.length];
    targets.set(type, targets.get(type)! + 1);
  }
  return Object.fromEntries(targets) as Partial<Record<VenueType, number>>;
}

async function runGeneration(
  userId: string,
  tripId: string,
  city: string,
  locale?: string,
  near?: { lat: number; lng: number },
) {
  const started = await TripsCollection.findOneAsync({ _id: tripId, userId, status: 'pending' });
  if (!started) return;
  const location = started.cityLat !== undefined && started.cityLng !== undefined
    ? { lat: started.cityLat, lng: started.cityLng, countryCode: started.cityCountryCode }
    : near;
  const searchCity = [city, started.cityCountry, location ? `coordinates ${location.lat}, ${location.lng}` : undefined].filter(Boolean).join(', ');

  // Access can be revoked while a task waits in Mongo. Do not spend provider
  // budget merely because the request was valid when it was enqueued.
  try {
    await requireProductAccess(userId);
  } catch {
    await TripsCollection.updateAsync({ _id: tripId, userId, status: 'pending' }, {
      $set: { status: 'cancelled', error: 'Access is no longer available.' },
    });
    await settleTrip(tripId, userId, []);
    return;
  }

  const profile = await loadProfile(userId);

  // Anchors carry the description the prompt aims at, so stale markup is
  // refreshed here rather than waiting for the person to name them again.
  // One anchor that cannot be refreshed leaves the others, and the stored
  // markup of that one, still usable.
  await Promise.allSettled(profile.anchors.map(placeId => cachePlace(placeId)));

  // Always recompute rather than trusting the stored copy: the profile is a
  // derivative, re-enrichment may have just rewritten the tags underneath it,
  // and a prompt built on last week's vocabulary is the bug we keep hitting.
  const current = await recomputeProfile(userId);
  const prompt = splitForPrompt(current.tagWeights);
  const requestTags = searchPromptTags(prompt.liked, prompt.disliked, started.searchPreferences);
  const likedTags = requestTags.liked.filter(tag => !started.excludedTags?.includes(tag));
  const dislikedTags = requestTags.disliked;

  const anchorPlaces = await PlacesCollection.find({
    placeId: { $in: current.anchors },
  }).fetchAsync();
  const allowedTypes = referenceVenueTypes(anchorPlaces, started.category)
    .filter(type => !started.venueType || type === started.venueType);
  if (!allowedTypes.length) throw new Error('NO_REFERENCE_TYPES');
  const rejectedPlaces = await PlacesCollection.find({
    placeId: { $in: current.rejected },
  }).fetchAsync();

  const upIds = effectiveEvents(await EventsCollection.find({ userId }).fetchAsync()).filter(event => event.signal === 'up').map(
    (e) => e.placeId!,
  );
  const upPlaces = await PlacesCollection.find({ placeId: { $in: upIds } }).fetchAsync();

  const llm = getLLMProvider();
  const previous = await TripsCollection.find({
    userId, status: 'ready',
    ...(started.cityPlaceId ? { cityPlaceId: started.cityPlaceId } : { city }),
  }).fetchAsync();
  const excluded = started.refresh ? [] : cityRecommendations(previous, { placeId: started.cityPlaceId ?? '', city });
  const excludedNames = new Set(excluded.map(place => venueKey(place.name)));
  const spent: { step: string; input: number; output: number }[] = [...(started.usage ?? [])];
  const neighbours = await findNeighbours(userId, { near, limit: 5 });
  // A city search is one taste decision over every eligible venue type. The
  // tabs are a view over these verified results; they must not cause separate
  // LLM searches. Only a deliberate category pagination/retry has venueType.
  const scope = started.requestedTypes?.length
    ? allowedTypes.filter(type => started.requestedTypes!.includes(type))
    : allowedTypes;
  if (!scope.length) throw new Error('NO_REFERENCE_TYPES');
  const narrow = Boolean(started.venueType);
  const category = narrow ? venueCategory(started.venueType!) : undefined;
  const matchingAnchors = anchorPlaces.filter(place => matchesVenueTypes(place, scope));
  const targets = narrow ? undefined : typeTargets(scope, matchingAnchors);
  let lastError: unknown = null;
  // Which stage was running, for the error journal.
  let step = 'discovery';

  for (let attempt = 0; attempt <= SILENT_RETRIES; attempt += 1) {
    step = 'discovery';
    try {
      // This remains one retrieval for the whole allowed set. The discovery
      // prompt requires coverage for every type, while the ranker makes the
      // final taste decision across that mixed pool.
      const pool = await candidatesFor(
        searchCity,
        locale,
        { add: (step, tokens) => spent.push({ step, ...tokens }) },
        excluded,
        category,
        scope,
        started.cityPlaceId,
      );
      const rankCandidates = async (candidates: Candidate[]) => {
        step = 'ranking';
        const ranked = await llm.rankTrip({
          searchPreferences: started.searchPreferences,
          city: searchCity,
          category,
          allowedTypes: scope,
          limit: narrow ? RECOMMENDATION_PAGE_SIZE : INITIAL_RECOMMENDATION_LIMIT,
          typeTargets: targets,
          excludeNames: excluded.map(place => place.name),
          likedTags,
          dislikedTags,
          anchors: matchingAnchors.map((p) => ({
            name: p.name,
            city: p.city,
            oneLiner: p.oneLiner,
            venueType: venueTypeOf(p),
          })),
          upPlaces: upPlaces.map((p) => p.name),
          downPlaces: rejectedPlaces.map((p) => p.name),
          candidates: await withFacts(candidates, city, location),
          neighbours: neighbours.filter(n => !excludedNames.has(venueKey(n.name))).map((n) => ({
            name: n.name,
            area: n.city,
            becauseOf: n.becauseOf.name,
            sharedAnchors: n.sharedAnchors,
          })),
          locale,
        }, { add: (step, tokens) => spent.push({ step, ...tokens }) });

        const takenNames = new Set(ranked.places.map((p) => p.n.toLowerCase()));
        const spares = candidates.filter((c) => !takenNames.has(c.n.toLowerCase()));
        const picks = ranked.places.filter(place => !excludedNames.has(venueKey(place.n)));
        step = 'verification';
        const resolved = await resolveAll(
          picks,
          spares,
          [city, started.cityCountry].filter(Boolean).join(', '),
          matchingAnchors.map(p => p.placeId),
          category,
          excluded,
          scope,
          location,
          targets,
        );
