          // Tags are an extra on the card; a place whose markup cannot be
          // fetched right now is still a verified place.
          const known = await cachePlace(place.placeId).catch((error) => {
            logFailure('place markup', tripId, error);
            return null;
          });
          return { ...place, tags: known?.tags, tagsRu: known?.tagsRu };
        }));
