          const refreshed = await candidatesFor(searchCity, locale,
            { add: (step, tokens) => spent.push({ step, ...tokens }) },
            excluded, category, scope, started.cityPlaceId,
            {
              // Use verified names, which can differ from model aliases.
              keep: batch.map(place => ({ n: place.name, a: place.area, s: place.why, dn: place.dayNight })),
              excludeNames: pool.candidates.filter(candidate => !batch.some(place => namesMatch(cleanName(candidate.n), place.name))).map(candidate => candidate.n),
            });
          const recovered = await rankCandidates(refreshed.candidates);
          // Keep verified first-pass results if a later provider response is
