async function resolveAll(
  picks: RawTripPlace[],
  spares: Candidate[],
  city: string,
  anchors: string[],
  category?: Category,
  excluded: TripPlace[] = [],
  allowedTypes: VenueType[] = [],
  location?: CityLocation,
  targets?: Partial<Record<VenueType, number>>,
): Promise<TripPlace[]> {
  const queue: RawTripPlace[] = [...picks, ...spares.map(spare => ({
    n: spare.n, a: spare.a, dn: spare.dn, w: spare.s, o: '', q: `${spare.n} ${city}`,
  }))];
  const out: TripPlace[] = [];
  const checked = new Set<string>();
  const limit = category ? RECOMMENDATION_PAGE_SIZE : INITIAL_RECOMMENDATION_LIMIT;
  const coveredTypes = !category && targets
    ? allowedTypes.filter((type) => (targets[type] ?? 0) > 0)
    : [];
  const hasCoverage = () =>
    coveredTypes.every((type) =>
      out.filter((place) => venueTypeOf(place) === type).length >= (targets?.[type] ?? 0),
    );

  // A short ranking still has a full spare pool. Fill available slots rather
  // than limiting the final batch to however many rows the model ranked.
  let failures = 0;
  for (const pick of queue) {
    const key = venueKey(pick.n);
    if (checked.has(key)) continue;
    checked.add(key);
    let resolved: TripPlace | null;
    try {
      resolved = await resolveTripPlace(pick, city, anchors, location);
      failures = 0;
    } catch (error) {
      failures += 1;
      if (failures >= MAX_CONSECUTIVE_RESOLVE_FAILURES) throw error;
      continue;
    }
    if (resolved?.verified && matchesVenueTypes(resolved, allowedTypes) &&
      (!category || resolved.category === category) &&
      uniqueRecommendations([resolved], [...excluded, ...out]).length > 0) out.push(resolved);
    if (out.length >= limit && (!coveredTypes.length || hasCoverage())) break;
  }

  if (!coveredTypes.length) return out;
  const required = coveredTypes.flatMap((type) =>
    out.filter((place) => venueTypeOf(place) === type).slice(0, targets?.[type] ?? 0),
  );
  return [...required, ...out]
    .filter((place, index, items) =>
      items.findIndex((item) => item.placeId === place.placeId) === index,
    )
    .slice(0, limit);
}

/** Below this the model has nothing to aim at and writes hedged filler. */
const MIN_ANCHORS = 5;

export const createTrip = defineOperation<
  { city: string; cityPlaceId?: string; locale?: string; category?: Category; venueType?: VenueType; refresh?: boolean; excludedTags?: string[]; searchPreferences?: SearchPreference[]; requestedTypes?: VenueType[] },
  { tripId: string }
>('trips.create', async (ctx, { city, cityPlaceId, locale, category, venueType, refresh, excludedTags, searchPreferences, requestedTypes: intentTypes }) => {
  const preferences = searchPreferences === undefined ? undefined : validatePreferences(searchPreferences);
  if (intentTypes !== undefined && (!Array.isArray(intentTypes) || !intentTypes.length || intentTypes.length > venueTypes.length || intentTypes.some(type => !venueTypes.includes(type)))) throw new Error('INVALID_VENUE_TYPE');
  if (refresh !== undefined && typeof refresh !== 'boolean') throw new Error('INVALID_REFRESH');
  if (excludedTags !== undefined && (!Array.isArray(excludedTags) || excludedTags.length > 100 || excludedTags.some(tag => typeof tag !== 'string' || !tag.trim() || tag.length > 80))) throw new Error('INVALID_TAGS');
  if (category !== undefined && !isCategory(category)) throw new Error('INVALID_CATEGORY');

