/** Upsert into the system-wide place cache and return the stored record. */
async function cachePlaceOnce(placeId: string, sessionToken?: string): Promise<Place | null> {
  const cached = await PlacesCollection.findOneAsync({ placeId });
  const complete = Boolean(cached?.city) && Boolean(cached?.lat);
  const stale = !cached?.verifiedAt ||
    Date.now() - cached.verifiedAt.getTime() > VERIFY_TTL_DAYS * 86_400_000;
  const needsType = cached?.primaryType === undefined;
  // Older nature markup needs fresh review evidence; cached records deliberately
  // omit review texts. Don't rebuild outdoor taste from a place name alone.
  const needsOutdoorMarkup = Boolean(cached && markupVersionFor(cached) === 6 && needsTasteMarkup(cached));

  if (cached && complete && !stale && !needsType && !needsTasteMarkup(cached)) {
    return isSelectablePlace(cached.types) ? cached : null;
  }

  // A cached record missing its city or coordinates was written before the
  // address parser was fixed — refetch rather than carry the gap forever.
  let base = complete && !stale && !needsType && !needsOutdoorMarkup
    ? cached!
    : await getPlacesProvider().details(placeId, { sessionToken });
  if (!base || !isSelectablePlace(base.types)) return null;
  // A one-time primary-type backfill need not regenerate existing taste markup.
  if (needsType && !stale && cached && !needsTasteMarkup({ ...base, tags: cached.tags, markupVersion: cached.markupVersion })) {
    base = { ...base, tags: cached.tags, tagsRu: cached.tagsRu, oneLiner: cached.oneLiner,
      markupVersion: cached.markupVersion, enrichedAt: cached.enrichedAt };
  }

  let enriched: Place;
  try {
    enriched = await enrich(base);
  } catch {
    // Saving a place must not depend on a descriptive AI response. Keep the
    // verified facts and retry tagging when this shared place is next touched.
    const {
      reviewTexts: _dropped,
      markupVersion: _oldVersion,
      enrichedAt: _oldEnrichedAt,
      ...storable
    } = base as PlaceDetails;
    enriched = {
      ...storable,
      category: categoryOf(base.types),
      tags: [],
      tagsRu: [],
      oneLiner: '',
      // A failed refresh (outdoor markup, an expired TTL) must not erase an
      // existing taste signal that every user shares. Keep its old version so
      // the next touch can retry.
      ...(cached?.tags?.length ? {
        tags: cached.tags, tagsRu: cached.tagsRu, oneLiner: cached.oneLiner,
        markupVersion: cached.markupVersion, enrichedAt: cached.enrichedAt,
      } : {}),
    };
    console.warn(`Place tagging failed; stored ${base.placeId} for retry`);
  }
  await PlacesCollection.upsertAsync({ placeId }, { $set: enriched });
  return enriched;
}

/** Coalesce concurrent cache misses: otherwise one click storm bills the
 * Places and LLM providers once per request for the same venue. */
export async function cachePlace(placeId: string, sessionToken?: string): Promise<Place | null> {
  const normalized = inputText(placeId, 'PLACE_ID', 3, 256);
  const active = inFlight.get(normalized);
  if (active) return active;
  const work = cachePlaceOnce(normalized, sessionToken).finally(() => inFlight.delete(normalized));
  inFlight.set(normalized, work);

