1	import { Meteor } from 'meteor/meteor';
2	import { defineOperation } from '../registry';
3	import { isSuperAdmin, requireSuperAdmin } from '../auth';
4	import { AccessRequestsCollection, ErrorLogsCollection, EventsCollection, PlacesCollection, ProductFeedbackCollection, ProfilesCollection, TripsCollection } from '../collections';
5	import { dateFilter, literalSearch, parseAdminList, readAdminPage } from '../adminPagination';
6	import type { AdminDetail, AdminListInput, AdminListKind, AdminOverview, AdminPage, AdminRow } from '/imports/domain/adminWorkspace';
7	
8	const collections = { requests: AccessRequestsCollection, users: Meteor.users, feedback: ProductFeedbackCollection, errors: ErrorLogsCollection };
9	const fields: Record<AdminListKind, Record<string, number>> = {
10	  requests: { createdAt: 1, email: 1, firstName: 1, lastName: 1, attribution: 1, status: 1, deliveryState: 1, lastError: 1 },
11	  users: { createdAt: 1, emails: 1, 'profile.name': 1, 'services.google.email': 1, roles: 1, isAdmin: 1, 'access.enabled': 1, activity: 1 },
12	  feedback: { createdAt: 1, userId: 1, text: 1, locale: 1, page: 1 },
13	  errors: { createdAt: 1, operation: 1, code: 1, name: 1, message: 1, actorUserId: 1, subjectEmail: 1 },
14	};
15	const emailOf = (user: any) => user?.emails?.[0]?.address ?? user?.services?.google?.email ?? user?._id ?? '—';
16	const deliveryOf = (row: any) => row.deliveryState ?? ({ processed: 'unconfirmed', delivery_failed: 'failed', awaiting_delivery: 'awaiting' } as Record<string, string>)[row.status] ?? 'not_sent';
17	const adminRole = { $or: [{ isAdmin: true }, { roles: 'superadmin' }] };
18	const aggregate = (collection: any, pipeline: any[]) => collection.rawCollection().aggregate(pipeline).toArray() as Promise<any[]>;
19	async function matchingUsers(query: RegExp): Promise<string[]> {
20	  return (await Meteor.users.find({ $or: [{ 'emails.address': query }, { 'services.google.email': query }, { 'profile.name': query }] }, { fields: { _id: 1 } }).fetchAsync()).map(row => row._id);
21	}
22	async function listFilter(input: ReturnType<typeof parseAdminList>) {
23	  const conditions: any[] = [dateFilter(input.from, input.to)];
24	  const { kind, status } = input;
25	  if (status !== 'all') {
26	    if (kind === 'users') conditions.push(status === 'superadmin' ? adminRole : status === 'user' ? { $nor: [adminRole] }
27	      : status === 'enabled' ? { 'access.enabled': true } : { 'access.enabled': { $ne: true } });
28	    if (kind === 'feedback') conditions.push({ locale: status });
29	    if (kind === 'requests') {
30	      const legacy: Record<string, any> = {
31	        unconfirmed: { status: 'processed' }, failed: { status: 'delivery_failed' }, awaiting: { status: 'awaiting_delivery' },
32	        not_sent: { status: { $nin: ['processed', 'delivery_failed', 'awaiting_delivery'] } },
33	      };
34	      conditions.push({ $or: [{ deliveryState: status }, ...(legacy[status] ? [{ deliveryState: null, ...legacy[status] }] : [])] });
35	    }
36	  }
37	  if (input.query) {
38	    const expression = literalSearch(input.query);
39	    const keys = kind === 'users' ? ['emails.address', 'services.google.email', 'profile.name']
40	      : kind === 'requests' ? ['email', 'firstName', 'lastName'] : kind === 'errors' ? ['operation', 'code', 'message', 'subjectEmail'] : ['text'];
41	    const alternatives: any[] = keys.map(key => ({ [key]: expression }));
42	    if (kind === 'errors' || kind === 'feedback') alternatives.push({ [kind === 'errors' ? 'actorUserId' : 'userId']: { $in: await matchingUsers(expression) } });
43	    conditions.push({ $or: alternatives });
44	  }
45	  return { $and: conditions };
46	}
47	async function serializeRows(kind: AdminListKind, rows: any[]): Promise<AdminRow[]> {
48	  if (kind === 'users') {
49	    const ids = rows.map(row => row._id);
50	    const [profiles, trips, events] = await Promise.all([
51	      ProfilesCollection.find({ userId: { $in: ids } }, { fields: { userId: 1, anchors: 1 } }).fetchAsync(),
52	      aggregate(TripsCollection, [{ $match: { userId: { $in: ids } } }, { $group: { _id: '$userId', last: { $max: '$createdAt' }, count: { $sum: { $cond: [{ $eq: ['$status', 'ready'] }, 1, 0] } } } }]),
53	      aggregate(EventsCollection, [{ $match: { userId: { $in: ids } } }, { $group: { _id: '$userId', last: { $max: '$createdAt' } } }]),
54	    ]);
55	    return rows.map(row => {
56	      const trip = trips.find(item => item._id === row._id), event = events.find(item => item._id === row._id);
57	      const dates = [trip?.last, event?.last].filter(Boolean) as Date[];
58	      return { id: row._id, email: emailOf(row), name: row.profile?.name, createdAt: row.createdAt, role: isSuperAdmin(row) ? 'superadmin' : 'user',
59	        enabled: !!row.access?.enabled, seeds: profiles.find(item => item.userId === row._id)?.anchors?.length ?? 0, trips: trip?.count ?? 0,
60	        lastActivity: row.activity?.at ?? dates.sort((a, b) => b.getTime() - a.getTime())[0],
61	        lastActivityCity: row.activity?.city, lastActivityCountry: row.activity?.country };
62	    });
63	  }
64	  const ids = [...new Set(rows.map(row => kind === 'errors' ? row.actorUserId : row.userId).filter(Boolean))];
65	  const people = ids.length ? await Meteor.users.find({ _id: { $in: ids } }, { fields: { emails: 1, 'services.google.email': 1 } }).fetchAsync() : [];
66	  const email = (id: string) => emailOf(people.find(row => row._id === id) ?? { _id: id });
67	  return rows.map(row => kind === 'requests'
68	    ? { id: row._id, email: row.email, name: [row.firstName, row.lastName].filter(Boolean).join(' '), createdAt: row.createdAt, status: deliveryOf(row), source: row.attribution?.source ?? 'direct', lastError: row.lastError }
69	    : kind === 'errors' ? { id: row._id, createdAt: row.createdAt, operation: row.operation, code: row.code ?? row.name, message: row.message, actorEmail: row.actorUserId ? email(row.actorUserId) : undefined, subjectEmail: row.subjectEmail }
70	      : { id: row._id, createdAt: row.createdAt, email: email(row.userId), text: row.text, locale: row.locale, page: row.page });
71	}
72	defineOperation<AdminListInput, AdminPage>('admin.workspace.list', async (ctx, raw) => {
73	  await requireSuperAdmin(ctx.userId);
74	  const input = parseAdminList(raw);
75	  const { rows, ...page } = await readAdminPage(collections[input.kind], await listFilter(input), input, fields[input.kind]);
76	  return { ...page, items: await serializeRows(input.kind, rows) };
77	});
78	defineOperation<{ kind: AdminListKind; id: string }, AdminDetail>('admin.workspace.detail', async (ctx, input) => {
79	  await requireSuperAdmin(ctx.userId);
80	  if (!input || !Object.hasOwn(collections, input.kind) || typeof input.id !== 'string' || !input.id || input.id.length > 200) throw new Meteor.Error('invalid-input', 'Invalid record');
81	  const collection: any = collections[input.kind];
82	  const row = await collection.findOneAsync(input.id, { fields: { ...fields[input.kind], ...(input.kind === 'errors' ? { details: 1, stack: 1, context: 1 } : {}) } });
83	  if (!row) throw new Meteor.Error('not-found', 'Record not found');
84	  const detail: AdminDetail = (await serializeRows(input.kind, [row]))[0];
85	  if (input.kind === 'errors') Object.assign(detail, { details: row.details, stack: row.stack, context: row.context });
86	  if (input.kind === 'users') {
87	    const profile = await ProfilesCollection.findOneAsync({ userId: row._id });
88	    const places = await PlacesCollection.find({ placeId: { $in: profile?.anchors ?? [] } }, { fields: { name: 1, city: 1 } }).fetchAsync();
89	    detail.places = places.map(place => ({ name: place.name, city: place.city }));
90	    detail.tags = Object.entries(profile?.tagWeights ?? {}).filter(([, value]) => value > 0).sort((a, b) => b[1] - a[1]).map(([tag]) => tag);
91	  }
92	  return detail;
93	});
94	defineOperation<void, AdminOverview>('admin.workspace.overview', async ctx => {
95	  await requireSuperAdmin(ctx.userId);
96	  const since = new Date(Date.now() - 7 * 86400000);
97	  const [users, activated, readyTrips, ratings, active, shared, signals, top, requests, awaiting, failed, errors24h, feedback] = await Promise.all([
98	    Meteor.users.find({}).countAsync(), ProfilesCollection.find({ 'anchors.4': { $exists: true } }).countAsync(),
99	    TripsCollection.find({ status: 'ready' }).countAsync(), EventsCollection.find({ signal: { $in: ['up', 'down'] } }).countAsync(),
100	    aggregate(EventsCollection, [{ $match: { createdAt: { $gte: since } } }, { $project: { userId: 1 } },
101	      { $unionWith: { coll: 'trips', pipeline: [{ $match: { createdAt: { $gte: since } } }, { $project: { userId: 1 } }] } }, { $group: { _id: '$userId' } }, { $count: 'count' }]),
102	    aggregate(ProfilesCollection, [{ $unwind: '$anchors' }, { $group: { _id: { place: '$anchors', user: '$userId' } } },
103	      { $group: { _id: '$_id.place', count: { $sum: 1 } } }, { $match: { count: { $gte: 2 } } }, { $count: 'count' }]),
104	    aggregate(EventsCollection, [{ $group: { _id: '$signal', count: { $sum: 1 } } }, { $sort: { count: -1, _id: 1 } }]),
105	    aggregate(EventsCollection, [{ $match: { signal: { $in: ['seed', 'up', 'saved'] }, placeId: { $type: 'string' } } },
106	      { $group: { _id: '$placeId', count: { $sum: 1 } } }, { $sort: { count: -1, _id: 1 } }, { $limit: 12 },
107	      { $lookup: { from: 'places', localField: '_id', foreignField: 'placeId', as: 'place' } },
108	      { $project: { count: 1, name: { $arrayElemAt: ['$place.name', 0] }, city: { $arrayElemAt: ['$place.city', 0] } } }]),
109	    AccessRequestsCollection.find(await listFilter(parseAdminList({ kind: 'requests', status: 'not_sent' }))).countAsync(),
