import { Meteor } from 'meteor/meteor';
import { defineOperation } from '../registry';
import { isSuperAdmin, requireSuperAdmin } from '../auth';
import { AccessRequestsCollection, ErrorLogsCollection, EventsCollection, PlacesCollection, ProductFeedbackCollection, ProfilesCollection, TripsCollection } from '../collections';
import { dateFilter, literalSearch, parseAdminList, readAdminPage } from '../adminPagination';
import type { AdminDetail, AdminListInput, AdminListKind, AdminOverview, AdminPage, AdminRow } from '/imports/domain/adminWorkspace';

const collections = { requests: AccessRequestsCollection, users: Meteor.users, feedback: ProductFeedbackCollection, errors: ErrorLogsCollection };
const fields: Record<AdminListKind, Record<string, number>> = {
  requests: { createdAt: 1, email: 1, firstName: 1, lastName: 1, attribution: 1, status: 1, deliveryState: 1, lastError: 1 },
  users: { createdAt: 1, emails: 1, 'profile.name': 1, 'services.google.email': 1, roles: 1, isAdmin: 1, 'access.enabled': 1, activity: 1 },
  feedback: { createdAt: 1, userId: 1, text: 1, locale: 1, page: 1 },
  errors: { createdAt: 1, operation: 1, code: 1, name: 1, message: 1, actorUserId: 1, subjectEmail: 1 },
};
const emailOf = (user: any) => user?.emails?.[0]?.address ?? user?.services?.google?.email ?? user?._id ?? '—';
const deliveryOf = (row: any) => row.deliveryState ?? ({ processed: 'unconfirmed', delivery_failed: 'failed', awaiting_delivery: 'awaiting' } as Record<string, string>)[row.status] ?? 'not_sent';
const adminRole = { $or: [{ isAdmin: true }, { roles: 'superadmin' }] };
const aggregate = (collection: any, pipeline: any[]) => collection.rawCollection().aggregate(pipeline).toArray() as Promise<any[]>;
async function matchingUsers(query: RegExp): Promise<string[]> {
  return (await Meteor.users.find({ $or: [{ 'emails.address': query }, { 'services.google.email': query }, { 'profile.name': query }] }, { fields: { _id: 1 } }).fetchAsync()).map(row => row._id);
}
async function listFilter(input: ReturnType<typeof parseAdminList>) {
  const conditions: any[] = [dateFilter(input.from, input.to)];
  const { kind, status } = input;
  if (status !== 'all') {
    if (kind === 'users') conditions.push(status === 'superadmin' ? adminRole : status === 'user' ? { $nor: [adminRole] }
      : status === 'enabled' ? { 'access.enabled': true } : { 'access.enabled': { $ne: true } });
    if (kind === 'feedback') conditions.push({ locale: status });
    if (kind === 'requests') {
      const legacy: Record<string, any> = {
        unconfirmed: { status: 'processed' }, failed: { status: 'delivery_failed' }, awaiting: { status: 'awaiting_delivery' },
        not_sent: { status: { $nin: ['processed', 'delivery_failed', 'awaiting_delivery'] } },
      };
      conditions.push({ $or: [{ deliveryState: status }, ...(legacy[status] ? [{ deliveryState: null, ...legacy[status] }] : [])] });
    }
  }
  if (input.query) {
    const expression = literalSearch(input.query);
    const keys = kind === 'users' ? ['emails.address', 'services.google.email', 'profile.name']
      : kind === 'requests' ? ['email', 'firstName', 'lastName'] : kind === 'errors' ? ['operation', 'code', 'message', 'subjectEmail'] : ['text'];
    const alternatives: any[] = keys.map(key => ({ [key]: expression }));
    if (kind === 'errors' || kind === 'feedback') alternatives.push({ [kind === 'errors' ? 'actorUserId' : 'userId']: { $in: await matchingUsers(expression) } });
    conditions.push({ $or: alternatives });
  }
  return { $and: conditions };
}
async function serializeRows(kind: AdminListKind, rows: any[]): Promise<AdminRow[]> {
  if (kind === 'users') {
    const ids = rows.map(row => row._id);
    const [profiles, trips, events] = await Promise.all([
      ProfilesCollection.find({ userId: { $in: ids } }, { fields: { userId: 1, anchors: 1 } }).fetchAsync(),
      aggregate(TripsCollection, [{ $match: { userId: { $in: ids } } }, { $group: { _id: '$userId', last: { $max: '$createdAt' }, count: { $sum: { $cond: [{ $eq: ['$status', 'ready'] }, 1, 0] } } } }]),
      aggregate(EventsCollection, [{ $match: { userId: { $in: ids } } }, { $group: { _id: '$userId', last: { $max: '$createdAt' } } }]),
    ]);
    return rows.map(row => {
      const trip = trips.find(item => item._id === row._id), event = events.find(item => item._id === row._id);
      const dates = [trip?.last, event?.last].filter(Boolean) as Date[];
      return { id: row._id, email: emailOf(row), name: row.profile?.name, createdAt: row.createdAt, role: isSuperAdmin(row) ? 'superadmin' : 'user',
        enabled: !!row.access?.enabled, seeds: profiles.find(item => item.userId === row._id)?.anchors?.length ?? 0, trips: trip?.count ?? 0,
        lastActivity: row.activity?.at ?? dates.sort((a, b) => b.getTime() - a.getTime())[0],
        lastActivityCity: row.activity?.city, lastActivityCountry: row.activity?.country };
    });
  }
  const ids = [...new Set(rows.map(row => kind === 'errors' ? row.actorUserId : row.userId).filter(Boolean))];
  const people = ids.length ? await Meteor.users.find({ _id: { $in: ids } }, { fields: { emails: 1, 'services.google.email': 1 } }).fetchAsync() : [];
  const email = (id: string) => emailOf(people.find(row => row._id === id) ?? { _id: id });
  return rows.map(row => kind === 'requests'
    ? { id: row._id, email: row.email, name: [row.firstName, row.lastName].filter(Boolean).join(' '), createdAt: row.createdAt, status: deliveryOf(row), source: row.attribution?.source ?? 'direct', lastError: row.lastError }
    : kind === 'errors' ? { id: row._id, createdAt: row.createdAt, operation: row.operation, code: row.code ?? row.name, message: row.message, actorEmail: row.actorUserId ? email(row.actorUserId) : undefined, subjectEmail: row.subjectEmail }
      : { id: row._id, createdAt: row.createdAt, email: email(row.userId), text: row.text, locale: row.locale, page: row.page });
}
defineOperation<AdminListInput, AdminPage>('admin.workspace.list', async (ctx, raw) => {
  await requireSuperAdmin(ctx.userId);
  const input = parseAdminList(raw);
  const { rows, ...page } = await readAdminPage(collections[input.kind], await listFilter(input), input, fields[input.kind]);
  return { ...page, items: await serializeRows(input.kind, rows) };
});
defineOperation<{ kind: AdminListKind; id: string }, AdminDetail>('admin.workspace.detail', async (ctx, input) => {
  await requireSuperAdmin(ctx.userId);
  if (!input || !Object.hasOwn(collections, input.kind) || typeof input.id !== 'string' || !input.id || input.id.length > 200) throw new Meteor.Error('invalid-input', 'Invalid record');
  const collection: any = collections[input.kind];
  const row = await collection.findOneAsync(input.id, { fields: { ...fields[input.kind], ...(input.kind === 'errors' ? { details: 1, stack: 1, context: 1 } : {}) } });
  if (!row) throw new Meteor.Error('not-found', 'Record not found');
  const detail: AdminDetail = (await serializeRows(input.kind, [row]))[0];
  if (input.kind === 'errors') Object.assign(detail, { details: row.details, stack: row.stack, context: row.context });
  if (input.kind === 'users') {
    const profile = await ProfilesCollection.findOneAsync({ userId: row._id });
    const places = await PlacesCollection.find({ placeId: { $in: profile?.anchors ?? [] } }, { fields: { name: 1, city: 1 } }).fetchAsync();
    detail.places = places.map(place => ({ name: place.name, city: place.city }));
    detail.tags = Object.entries(profile?.tagWeights ?? {}).filter(([, value]) => value > 0).sort((a, b) => b[1] - a[1]).map(([tag]) => tag);
  }
  return detail;
});
defineOperation<void, AdminOverview>('admin.workspace.overview', async ctx => {
  await requireSuperAdmin(ctx.userId);
  const since = new Date(Date.now() - 7 * 86400000);
  const [users, activated, readyTrips, ratings, active, shared, signals, top, requests, awaiting, failed, errors24h, feedback] = await Promise.all([
    Meteor.users.find({}).countAsync(), ProfilesCollection.find({ 'anchors.4': { $exists: true } }).countAsync(),
    TripsCollection.find({ status: 'ready' }).countAsync(), EventsCollection.find({ signal: { $in: ['up', 'down'] } }).countAsync(),
    aggregate(EventsCollection, [{ $match: { createdAt: { $gte: since } } }, { $project: { userId: 1 } },
      { $unionWith: { coll: 'trips', pipeline: [{ $match: { createdAt: { $gte: since } } }, { $project: { userId: 1 } }] } }, { $group: { _id: '$userId' } }, { $count: 'count' }]),
    aggregate(ProfilesCollection, [{ $unwind: '$anchors' }, { $group: { _id: { place: '$anchors', user: '$userId' } } },
      { $group: { _id: '$_id.place', count: { $sum: 1 } } }, { $match: { count: { $gte: 2 } } }, { $count: 'count' }]),
    aggregate(EventsCollection, [{ $group: { _id: '$signal', count: { $sum: 1 } } }, { $sort: { count: -1, _id: 1 } }]),
    aggregate(EventsCollection, [{ $match: { signal: { $in: ['seed', 'up', 'saved'] }, placeId: { $type: 'string' } } },
      { $group: { _id: '$placeId', count: { $sum: 1 } } }, { $sort: { count: -1, _id: 1 } }, { $limit: 12 },
      { $lookup: { from: 'places', localField: '_id', foreignField: 'placeId', as: 'place' } },
      { $project: { count: 1, name: { $arrayElemAt: ['$place.name', 0] }, city: { $arrayElemAt: ['$place.city', 0] } } }]),
    AccessRequestsCollection.find(await listFilter(parseAdminList({ kind: 'requests', status: 'not_sent' }))).countAsync(),
    AccessRequestsCollection.find(await listFilter(parseAdminList({ kind: 'requests', status: 'awaiting' }))).countAsync(),
    AccessRequestsCollection.find(await listFilter(parseAdminList({ kind: 'requests', status: 'failed' }))).countAsync(),
    ErrorLogsCollection.find({ createdAt: { $gte: new Date(Date.now() - 86400000) } }).countAsync(), ProductFeedbackCollection.find({}).countAsync(),
  ]);
  return { users, activated, readyTrips, ratings, active7d: active[0]?.count ?? 0, sharedPlaces: shared[0]?.count ?? 0,
    requests, awaiting, failed, errors24h, feedback, signals: signals.map(row => ({ name: row._id, count: row.count })),
    topPlaces: top.map(row => ({ name: row.name ?? '—', city: row.city ?? '', count: row.count })) };
});

