import { setting } from '/server/runtimeSettings';
import { Meteor } from 'meteor/meteor';
import { ProviderBudgetsCollection } from './collections';


function day(): string {
  return new Date().toISOString().slice(0, 10);
}

/** Photos count apart from the rest of Places: a page of cards must not be able
 * to use up the budget that search and generation depend on. */
export type BudgetedProvider = 'places' | 'places-photo' | 'llm';

const limitOf = (provider: BudgetedProvider) => provider === 'places'
  ? setting('PLACES_DAILY_REQUEST_LIMIT')
  : provider === 'places-photo'
    ? setting('PLACES_PHOTO_DAILY_REQUEST_LIMIT')
    : setting('LLM_DAILY_REQUEST_LIMIT');

function assertEnabled(provider: BudgetedProvider) {
  if (setting<boolean>(provider === 'llm' ? 'LLM_DISABLED' : 'PLACES_DISABLED')) {
    throw new Meteor.Error('provider-disabled', 'This provider is temporarily unavailable');
  }
}

/** Reserve before the external request. We deliberately do not refund failed
 * calls: after a request leaves the process, it may already be billable. */
export async function reserveProviderRequest(provider: BudgetedProvider) {
  assertEnabled(provider);
  const period = day();
  const limit = limitOf(provider);
  const changed = await ProviderBudgetsCollection.updateAsync(
    { provider, period, requests: { $lt: limit } },
    { $inc: { requests: 1 }, $set: { updatedAt: new Date() } },
  );
  if (changed === 1) return;
  const existing = await ProviderBudgetsCollection.findOneAsync({ provider, period });
  if (existing) throw new Meteor.Error('provider-budget-exceeded', 'Provider daily budget reached');
  try {
    await ProviderBudgetsCollection.insertAsync({ provider, period, requests: 1, updatedAt: new Date() });
  } catch (error: any) {
    if (error?.code === 11000) return reserveProviderRequest(provider);
    throw error;
  }
}

/** Throws what `reserveProviderRequest` would throw, without spending anything.
 * For callers that charge a person before the first provider call. */
export async function assertProviderAvailable(provider: BudgetedProvider) {
  assertEnabled(provider);
  const existing = await ProviderBudgetsCollection.findOneAsync({ provider, period: day() });
  if (existing && existing.requests >= limitOf(provider)) {
    throw new Meteor.Error('provider-budget-exceeded', 'Provider daily budget reached');
  }
}

export async function ensureProviderBudgetIndexes() {
  await ProviderBudgetsCollection.rawCollection().createIndex({ provider: 1, period: 1 }, { unique: true });
}

