1	import type { Candidate, RankInput, RankedTrip } from './prompt';
2	
3	export interface PlaceFacts {
4	  name: string;
5	  city: string;
6	  area?: string;
7	  types?: string[];
8	  primaryType?: string | null;
9	  reviews?: string[];
10	  priceLevel?: number;
11	  /**
12	   * Tags the corpus already uses. Reusing them is what makes rarity mean
13	   * anything: a vocabulary invented fresh per place gives every tag a count
14	   * of one, and IDF then says every tag is equally rare.
15	   */
16	  vocabulary?: string[];
17	}
18	
19	export interface PlaceMarkup {
20	  /**
21	   * Canonical tags, in English. Tags are shared across every user, so they
22	   * have to live in one language: a per-user vocabulary would split the
23	   * corpus, break rarity, and make the shared place cache useless.
24	   */
25	  tags: string[];
26	  /** The same tags in Russian, index for index — display only. */
27	  tagsRu: string[];
28	  /** One phrase of what the place actually is — the anchor description. */
29	  oneLiner: string;
30	}
31	
32	/**
33	 * LLM provider. Provider-agnostic on purpose: the mock runs the whole flow
34	 * locally with zero API spend, and a real key switches it over with no
35	 * changes anywhere else.
36	 */
37	/** What a call actually consumed — the only honest basis for a cost estimate. */
38	export interface TokenUsage {
39	  input: number;
40	  output: number;
41	}
42	
