import type { Candidate, RankInput, RankedTrip } from './prompt';

export interface PlaceFacts {
  name: string;
  city: string;
  area?: string;
  types?: string[];
  primaryType?: string | null;
  reviews?: string[];
  priceLevel?: number;
  /**
   * Tags the corpus already uses. Reusing them is what makes rarity mean
   * anything: a vocabulary invented fresh per place gives every tag a count
   * of one, and IDF then says every tag is equally rare.
   */
  vocabulary?: string[];
}

export interface PlaceMarkup {
  /**
   * Canonical tags, in English. Tags are shared across every user, so they
   * have to live in one language: a per-user vocabulary would split the
   * corpus, break rarity, and make the shared place cache useless.
   */
  tags: string[];
  /** The same tags in Russian, index for index — display only. */
  tagsRu: string[];
  /** One phrase of what the place actually is — the anchor description. */
  oneLiner: string;
}

/**
 * LLM provider. Provider-agnostic on purpose: the mock runs the whole flow
 * locally with zero API spend, and a real key switches it over with no
 * changes anywhere else.
 */
/** What a call actually consumed — the only honest basis for a cost estimate. */
export interface TokenUsage {
  input: number;
  output: number;
}

/** Accumulates across a generation so a trip can carry its own price tag. */
export interface UsageSink {
  add(step: string, usage: TokenUsage): void;
}

export interface LLMProvider {
  readonly kind: 'anthropic' | 'openai';
  parseSearch?(query: string, locale: string): Promise<import('/imports/domain/searchIntent').SearchIntent>;

  /**
   * Pass 1 — retrieval within reference venue types. No taste tags involved;
   * the pool is shared by city and allowed type scope.
   */
  findCandidates(city: string, locale?: string, usage?: UsageSink, category?: import('/imports/domain/categories').Category, excludeNames?: string[], allowedTypes?: import('/imports/domain/venueTypes').VenueType[]): Promise<Candidate[]>;

  /** Pass 2 — ranking. Personal, no web search: it works off the candidates. */
  rankTrip(input: RankInput, usage?: UsageSink): Promise<RankedTrip>;

  /**
   * Spec 9.2 — enrichment. A place is described once for the whole system,
   * from Places facts and reviews. Every later user reads the same markup.
   */
  tagPlace(facts: PlaceFacts): Promise<PlaceMarkup>;
}

