import { setting } from '/server/runtimeSettings';
import type { PlacesProvider } from './places/provider';
import type { LLMProvider } from './llm/provider';
import { googlePlacesProvider } from './places/googleProvider';
import { anthropicProvider } from './llm/anthropicProvider';
import { openaiProvider } from './llm/openaiProvider';
import { assertProviderAvailable, reserveProviderRequest } from './providerBudget';

/**
 * Provider selection.
 *
 * There are no built-in stand-ins: fabricated places look like a broken
 * product rather than a missing key, and every one we shipped ended up on
 * someone's screen. A missing key says so, loudly.
 *
 * Tests install their own doubles through `overrideProviders` — those live in
 * the test files, not in the app.
 */

let placesOverride: PlacesProvider | null = null;
let llmOverride: LLMProvider | null = null;

export function overrideProviders(next: {
  places?: PlacesProvider | null;
  llm?: LLMProvider | null;
}) {
  if ('places' in next) placesOverride = next.places ?? null;
  if ('llm' in next) llmOverride = next.llm ?? null;
}

export function getPlacesProvider(): PlacesProvider {
  if (placesOverride) return placesOverride;
  if (process.env.GOOGLE_PLACES_KEY) return {
    kind: googlePlacesProvider.kind,
    async search(...args) { await reserveProviderRequest('places'); return googlePlacesProvider.search(...args); },
    async searchCities(...args) { await reserveProviderRequest('places'); return googlePlacesProvider.searchCities(...args); },
    async cityNear(...args) {
      await reserveProviderRequest('places');
      await reserveProviderRequest('places');
      return googlePlacesProvider.cityNear(...args);
    },
    async details(...args) { await reserveProviderRequest('places'); return googlePlacesProvider.details(...args); },
    async photo(...args) {
      // Fetching a visible photo consists of metadata and media requests, paid
      // from their own budget so a page of cards cannot starve search.
      await reserveProviderRequest('places-photo');
      await reserveProviderRequest('places-photo');
      return googlePlacesProvider.photo(...args);
    },
    async nearby(...args) { await reserveProviderRequest('places'); return googlePlacesProvider.nearby(...args); },
  };

  throw new Error('GOOGLE_PLACES_KEY is not set — add it to .env to search places.');
}

export function getLLMProvider(): LLMProvider {
  if (llmOverride) return llmOverride;

  const explicit = setting<string>('LLM_PROVIDER');
  const provider = explicit === 'openai' ? openaiProvider
    : explicit === 'anthropic' ? anthropicProvider
      : process.env.OPENAI_API_KEY ? openaiProvider
        : process.env.ANTHROPIC_API_KEY ? anthropicProvider : null;
  if (provider) return {
    kind: provider.kind,
    async parseSearch(...args) {
      if (!provider.parseSearch) throw new Error('ASSISTANT_UNAVAILABLE');
      await reserveProviderRequest('llm');
      return provider.parseSearch(...args);
    },
    async findCandidates(...args) { await reserveProviderRequest('llm'); return provider.findCandidates(...args); },
    async rankTrip(...args) { await reserveProviderRequest('llm'); return provider.rankTrip(...args); },
    async tagPlace(...args) { await reserveProviderRequest('llm'); return provider.tagPlace(...args); },
  };

  throw new Error('No LLM key set — add OPENAI_API_KEY or ANTHROPIC_API_KEY to .env.');
}

/**
 * Fail before a person's trip allowance is spent, not after: the same errors
 * the first LLM call would raise (no key, switched off, daily budget used up).
 */
export async function assertLLMAvailable() {
  if (llmOverride) return;
  getLLMProvider();
  await assertProviderAvailable('llm');
}

