import { Meteor } from 'meteor/meteor';
import { startTransport } from './transport';
import { seedAdmin } from './seedAdmin';
import './accountsConfig';
import './socialMetadata';
import { ensureQueueIndexes, startWorker } from '/imports/api/queue/queue';
import { CityCandidatesCollection, DraftsCollection, ErrorLogsCollection, EventsCollection, PlacesCollection, ProfilesCollection, TripsCollection, UsageQuotasCollection } from '/imports/api/collections';
import { ensureRequestRateLimitIndexes } from '/imports/api/requestRateLimit';
import { ensureProviderBudgetIndexes } from '/imports/api/providerBudget';
import { WishlistCollection } from '/imports/api/collections';
import { ProductFeedbackCollection } from '/imports/api/collections';
import { configureMailTransport } from './mailConfig';
import { ensureAccessRequestIndexes } from './accessRequestIndexes';
import { initializeRuntimeSettings, migrateInterestBatchRate, migrateRankingPrompt } from './runtimeSettings';
import { ensureAdminIndexes } from './adminIndexes';

configureMailTransport();

Meteor.startup(async () => {
  await initializeRuntimeSettings();
  await migrateInterestBatchRate();
  await migrateRankingPrompt();
  await ensureAdminIndexes();
  await seedAdmin();
  await ensureRequestRateLimitIndexes();
  await ensureProviderBudgetIndexes();
  startTransport();

  // Background work runs through the queue, so it outlives requests, tabs and
  // restarts; finished tasks expire after a month via a TTL index.
  await ensureQueueIndexes();
  await ensureAccessRequestIndexes();
  await ErrorLogsCollection.rawCollection().createIndex({ createdAt: -1 });
  await ProductFeedbackCollection.rawCollection().createIndex({ createdAt: -1, _id: -1 });
  await ErrorLogsCollection.rawCollection().createIndex({ createdAt: 1 }, { expireAfterSeconds: 180 * 24 * 60 * 60 });
  await UsageQuotasCollection.rawCollection().createIndex({ userId: 1, period: 1 }, { unique: true });
  await PlacesCollection.rawCollection().createIndex({ placeId: 1 }, { unique: true });
  await CityCandidatesCollection.rawCollection().createIndex({ city: 1 }, { unique: true });
  await ProfilesCollection.rawCollection().createIndex({ userId: 1 }, { unique: true });
  await WishlistCollection.rawCollection().createIndex({ userId: 1, placeId: 1 }, { unique: true });
  await DraftsCollection.rawCollection().createIndex({ userId: 1 }, { unique: true });
  await TripsCollection.rawCollection().createIndex({ userId: 1, status: 1, createdAt: -1 });
  await TripsCollection.rawCollection().createIndex({ userId: 1, cityPlaceId: 1, createdAt: 1 });
  await EventsCollection.rawCollection().createIndex({ userId: 1, createdAt: -1 });
  await EventsCollection.rawCollection().createIndex({ signal: 1, placeId: 1, userId: 1 });
  await PlacesCollection.rawCollection().createIndex({ city: 1 });
  startWorker();
});

