1	import { setting } from '/server/runtimeSettings';
2	import type { LLMProvider, PlaceFacts, PlaceMarkup, UsageSink } from './provider';
3	import { searchIntentPrompt } from './searchIntentPrompt';
4	import { parseSearchIntent } from '/imports/domain/searchIntent';
5	import { venueTypes } from '/imports/domain/venueTypes';
6	import { buildTaggingPrompt } from './taggingPrompt';
7	import { fetchWithRetry } from '../fetchRetry';
8	import {
9	  buildDiscoveryPrompt,
10	  buildRankingPrompt,
11	  extractCandidates,
12	  extractRankedTrip,
13	  type Candidate,
14	  type RankInput,
15	  type RankedTrip,
16	} from './prompt';
17	
18	/**
19	 * OpenAI, in the same two passes as every other provider.
20	 *
21	 * Pass 1 searches the web wide and impersonally (cacheable per city); pass 2
22	 * ranks the candidates for one person and needs no search. Raw HTTP against
23	 * the Responses API — the tool surface is where web search lives.
24	 *
25	 * Model ids move faster than this file: both are env-configurable, and the
26	 * defaults are only a starting point.
27	 */
28	
29	/** Enrichment is a small, high-volume call — a cheaper model fits. */
30	
31	const BASE = process.env.OPENAI_BASE_URL ?? 'https://api.openai.com/v1';
32	
33	// Enforce the wire format, rather than relying on the prompt's JSON instruction.
34	const stringField = { type: 'string' };
35	const dayNight = { type: 'string', enum: ['day', 'night'] };
36	const objectSchema = (properties: Record<string, unknown>) => ({
37	  type: 'object', properties, required: Object.keys(properties), additionalProperties: false,
38	});
39	const responseSchemas: Record<string, unknown> = {
40	  assistant: objectSchema({
41	    cityQuery: stringField,
42	    types: { type: 'array', maxItems: venueTypes.length, items: { type: 'string', enum: venueTypes } },
43	    preferences: { type: 'array', items: objectSchema({ tag: stringField, label: stringField, exclude: { type: 'boolean' } }) },
44	    clarification: stringField,
45	  }),
46	  discovery: objectSchema({
47	    places: { type: 'array', maxItems: 26, items: objectSchema({ n: stringField, a: stringField, s: stringField, dn: dayNight }) },
48	  }),
49	  tagging: objectSchema({
50	    tags: { type: 'array', items: stringField },
51	    tagsRu: { type: 'array', items: stringField },
52	    oneLiner: stringField,
53	  }),
54	};
55	
56	/** The list is capped at what the prompt asked for, so the schema is built per request. */
57	const rankingSchema = (limit: number) => objectSchema({
58	  places: { type: 'array', maxItems: limit, items: objectSchema({
59	    n: stringField, a: stringField, dn: dayNight, wild: { type: 'boolean' }, w: stringField, o: stringField, q: stringField,
60	  }) },
61	  rejected: { type: 'array', maxItems: 3, items: objectSchema({ n: stringField, a: stringField, why: stringField }) },
62	});
63	
64	
65	async function respond(
66	  model: string,
67	  input: string,
68	  webSearch: boolean,
69	  maxOutputTokens: number,
70	  usage?: UsageSink,
71	  step = 'call',
72	  schema: unknown = responseSchemas[step],
73	): Promise<string> {
74	  const key = process.env.OPENAI_API_KEY;
75	  if (!key) throw new Error('OPENAI_API_KEY is not set');
76	
77	  // The assistant answers a person who is waiting; the other steps run in the
78	  // background. Only explicit "try again" answers are repeated: after a timeout
79	  // the provider may already have run (and billed) the request.
80	  const timeoutMs = step === 'assistant'
81	    ? Math.min(setting('LLM_REQUEST_TIMEOUT_MS'), setting('ASSISTANT_REQUEST_TIMEOUT_MS'))
82	    : setting<number>('LLM_REQUEST_TIMEOUT_MS');
83	  const res = await fetchWithRetry(`${BASE}/responses`, {
84	    method: 'POST',
85	    headers: {
86	      'content-type': 'application/json',
87	      authorization: `Bearer ${key}`,
88	    },
89	    body: JSON.stringify({
90	      model,
91	      input,
92	      max_output_tokens: maxOutputTokens,
93	      ...(schema ? { text: { format: {
94	        type: 'json_schema', name: `verger_${step}`, strict: true, schema,
95	      } } } : {}),
96	      // Original GPT-5 defaults to reasoning that can consume the entire
97	      // small JSON budget before producing any visible text.
98	      ...(/^gpt-5(?:-(?:mini|nano))?(?:-\d{4}-\d{2}-\d{2})?$/.test(model)
99	        ? { reasoning: { effort: ['tagging', 'assistant'].includes(step) ? 'minimal' : 'low' } }
100	        : {}),
101	      ...(webSearch ? { tools: [{ type: 'web_search' }], max_tool_calls: setting('LLM_MAX_WEB_SEARCH_CALLS') } : {}),
102	    }),
103	  }, { timeoutMs, totalMs: step === 'assistant' ? timeoutMs : timeoutMs * 2, retryTransportErrors: false });
104	
105	  if (!res.ok) {
106	    const failure = await res.json().catch(() => null) as { error?: { code?: unknown } } | null;
107	    // Only a bounded error code enters server logs, never provider messages,
108	    // request contents or credentials. 429 alone cannot distinguish billing
109	    // failures from a temporary request-rate limit.
110	    const code = failure?.error?.code;
111	    const safeCode = typeof code === 'string' && /^[a-z0-9_]{1,80}$/i.test(code) ? ` (${code})` : '';
112	    throw new Error(`OpenAI request failed: ${res.status}${safeCode}`);
113	  }
114	
115	  const data: any = await res.json();
116	
117	  // Reported by the API, not estimated: token counts are the only thing that
118	  // makes "what does a trip cost" answerable instead of guessed.
119	  usage?.add(step, {
120	    input: data.usage?.input_tokens ?? 0,
121	    output: data.usage?.output_tokens ?? 0,
122	  });
123	
124	  try {
125	    return textOf(data);
126	  } catch (error) {
127	    // Numeric usage and an internal stage label identify truncation without
128	    // logging prompts, response bodies or credentials.
129	    if (data.status === 'incomplete' && error instanceof Error) {
130	      const output = Number(data.usage?.output_tokens) || 0;
131	      const reasoning = Number(data.usage?.output_tokens_details?.reasoning_tokens) || 0;
132	      throw new Error(`${error.message}: ${step}, budget ${maxOutputTokens}, output ${output}, reasoning ${reasoning}`);
133	    }
134	    throw error;
135	  }
136	}
137	
138	/**
139	 * Pull the text out by walking the output blocks, not by indexing into them:
140	 * a web-search turn puts tool calls in the same array as the message.
141	 */
142	function textOf(data: any): string {
143	  // Even valid-looking JSON must not be accepted from a truncated response.
144	  if (data.status === 'incomplete') {
145	    const reason = data.incomplete_details?.reason === 'max_output_tokens'
146	      ? 'max_output_tokens' : 'other';
147	    throw new Error(`OpenAI response incomplete (${reason})`);
148	  }
149	  if (data.status && data.status !== 'completed') throw new Error('OpenAI response not completed');
150	  if ((data.output ?? []).some((item: any) =>
151	    (item?.content ?? []).some((part: any) => part?.type === 'refusal'))) {
152	    throw new Error('OpenAI response refused');
153	  }
154	  if (typeof data.output_text === 'string' && data.output_text.length > 0) {
155	    return data.output_text;
156	  }
157	
158	  const chunks: string[] = [];
159	  for (const item of data.output ?? []) {
160	    for (const part of item?.content ?? []) {
161	      if (part?.type === 'output_text' && typeof part.text === 'string') chunks.push(part.text);
162	    }
163	  }
164	
165	  if (chunks.length === 0) throw new Error('OpenAI response carried no text');
166	  return chunks.join('\n');
167	}
168	
169	export const openaiProvider: LLMProvider = {
170	  kind: 'openai',
171	  async parseSearch(query, locale) {
172	    return parseSearchIntent(await respond(setting<string>('OPENAI_TAGGING_MODEL'), searchIntentPrompt(query, locale), false, 2000, undefined, 'assistant'));
173	  },
174	
175	  async tagPlace(facts: PlaceFacts): Promise<PlaceMarkup> {
176	    const text = await respond(
177	      setting<string>('OPENAI_TAGGING_MODEL'),
178	      buildTaggingPrompt(facts),
179	      false,
180	      setting('OPENAI_MAX_OUTPUT_TAGGING'),
181	      undefined,
182	      'tagging',
183	    );
184	
185	    const start = text.indexOf('{');
186	    const end = text.lastIndexOf('}');
187	    if (start === -1 || end === -1) throw new Error('OpenAI place markup is invalid');
188	
189	    const parsed = JSON.parse(text.slice(start, end + 1));
190	    if (!Array.isArray(parsed?.tags) || !parsed.tags.length ||
191	        !parsed.tags.every((tag: unknown) => typeof tag === 'string' && tag.trim()) ||
192	        !Array.isArray(parsed.tagsRu) || parsed.tagsRu.length !== parsed.tags.length ||
193	        !parsed.tagsRu.every((tag: unknown) => typeof tag === 'string' && tag.trim()) ||
194	        typeof parsed.oneLiner !== 'string' || !parsed.oneLiner.trim()) {
195	      throw new Error('OpenAI place markup is invalid');
196	    }
197	    return {
198	      tags: Array.isArray(parsed?.tags) ? (parsed.tags as string[]) : [],
199	      tagsRu: Array.isArray(parsed?.tagsRu) ? (parsed.tagsRu as string[]) : [],
200	      oneLiner: typeof parsed?.oneLiner === 'string' ? parsed.oneLiner : '',
201	    };
202	  },
203	
204	  async findCandidates(city, locale, usage, category, excludeNames, allowedTypes): Promise<Candidate[]> {
205	    // The cap includes reasoning, not just the 26-venue JSON. A live GPT-5
206	    // discovery exhausted 6000 tokens with 4800 spent on reasoning alone.
207	    return extractCandidates(
208	      await respond(setting<string>('OPENAI_MODEL'), buildDiscoveryPrompt(city, locale, category, excludeNames, allowedTypes, setting<string>('PROMPT_DISCOVERY')), true, setting('OPENAI_MAX_OUTPUT_DISCOVERY'), usage, 'discovery'),
209	    );
210	  },
211	
212	  async rankTrip(input: RankInput, usage?: UsageSink): Promise<RankedTrip> {
213	    // No web search here: the candidates are already on the table, and search
214	    // would only let the model wander off the pool it was given.
215	    // Without a limit the prompt asks for seven places plus the wildcard.
216	    const limit = input.limit ?? 8;
217	    return extractRankedTrip(
218	      await respond(setting<string>('OPENAI_MODEL'), buildRankingPrompt(input, setting<string>('PROMPT_RANKING')), false, setting('OPENAI_MAX_OUTPUT_RANKING'), usage, 'ranking', rankingSchema(limit)),
219	      limit,
220	    );
221	  },
222	};
223

