 * the Responses API — the tool surface is where web search lives.
 *
 * Model ids move faster than this file: both are env-configurable, and the
 * defaults are only a starting point.
 */

/** Enrichment is a small, high-volume call — a cheaper model fits. */

const BASE = process.env.OPENAI_BASE_URL ?? 'https://api.openai.com/v1';

// Enforce the wire format, rather than relying on the prompt's JSON instruction.
const stringField = { type: 'string' };
const dayNight = { type: 'string', enum: ['day', 'night'] };
const objectSchema = (properties: Record<string, unknown>) => ({
  type: 'object', properties, required: Object.keys(properties), additionalProperties: false,
});
const responseSchemas: Record<string, unknown> = {
  assistant: objectSchema({
    cityQuery: stringField,
    types: { type: 'array', maxItems: venueTypes.length, items: { type: 'string', enum: venueTypes } },
    preferences: { type: 'array', items: objectSchema({ tag: stringField, label: stringField, exclude: { type: 'boolean' } }) },
    clarification: stringField,
  }),
  discovery: objectSchema({
    places: { type: 'array', maxItems: 26, items: objectSchema({ n: stringField, a: stringField, s: stringField, dn: dayNight }) },
  }),
  tagging: objectSchema({
    tags: { type: 'array', items: stringField },
    tagsRu: { type: 'array', items: stringField },
    oneLiner: stringField,
  }),
};

/** The list is capped at what the prompt asked for, so the schema is built per request. */
const rankingSchema = (limit: number) => objectSchema({
  places: { type: 'array', maxItems: limit, items: objectSchema({
    n: stringField, a: stringField, dn: dayNight, wild: { type: 'boolean' }, w: stringField, o: stringField, q: stringField,
  }) },
  rejected: { type: 'array', maxItems: 3, items: objectSchema({ n: stringField, a: stringField, why: stringField }) },
});


async function respond(
  model: string,
  input: string,
  webSearch: boolean,
  maxOutputTokens: number,
  usage?: UsageSink,
  step = 'call',
  schema: unknown = responseSchemas[step],
): Promise<string> {
  const key = process.env.OPENAI_API_KEY;
  if (!key) throw new Error('OPENAI_API_KEY is not set');

  // The assistant answers a person who is waiting; the other steps run in the
  // background. Only explicit "try again" answers are repeated: after a timeout
  // the provider may already have run (and billed) the request.
  const timeoutMs = step === 'assistant'
    ? Math.min(setting('LLM_REQUEST_TIMEOUT_MS'), setting('ASSISTANT_REQUEST_TIMEOUT_MS'))
    : setting<number>('LLM_REQUEST_TIMEOUT_MS');
  const res = await fetchWithRetry(`${BASE}/responses`, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      authorization: `Bearer ${key}`,
    },
    body: JSON.stringify({
      model,
      input,
      max_output_tokens: maxOutputTokens,
      ...(schema ? { text: { format: {
        type: 'json_schema', name: `verger_${step}`, strict: true, schema,
      } } } : {}),
      // Original GPT-5 defaults to reasoning that can consume the entire
      // small JSON budget before producing any visible text.
      ...(/^gpt-5(?:-(?:mini|nano))?(?:-\d{4}-\d{2}-\d{2})?$/.test(model)
        ? { reasoning: { effort: ['tagging', 'assistant'].includes(step) ? 'minimal' : 'low' } }
        : {}),
      ...(webSearch ? { tools: [{ type: 'web_search' }], max_tool_calls: setting('LLM_MAX_WEB_SEARCH_CALLS') } : {}),
    }),
  }, { timeoutMs, totalMs: step === 'assistant' ? timeoutMs : timeoutMs * 2, retryTransportErrors: false });

  if (!res.ok) {
    const failure = await res.json().catch(() => null) as { error?: { code?: unknown } } | null;
    // Only a bounded error code enters server logs, never provider messages,
    // request contents or credentials. 429 alone cannot distinguish billing
    // failures from a temporary request-rate limit.
    const code = failure?.error?.code;
    const safeCode = typeof code === 'string' && /^[a-z0-9_]{1,80}$/i.test(code) ? ` (${code})` : '';
    throw new Error(`OpenAI request failed: ${res.status}${safeCode}`);
  }

  const data: any = await res.json();

  // Reported by the API, not estimated: token counts are the only thing that
  // makes "what does a trip cost" answerable instead of guessed.
  usage?.add(step, {
    input: data.usage?.input_tokens ?? 0,
    output: data.usage?.output_tokens ?? 0,
  });

  try {
    return textOf(data);
  } catch (error) {
    // Numeric usage and an internal stage label identify truncation without
    // logging prompts, response bodies or credentials.
    if (data.status === 'incomplete' && error instanceof Error) {
      const output = Number(data.usage?.output_tokens) || 0;
      const reasoning = Number(data.usage?.output_tokens_details?.reasoning_tokens) || 0;
      throw new Error(`${error.message}: ${step}, budget ${maxOutputTokens}, output ${output}, reasoning ${reasoning}`);
    }
    throw error;
  }
}

/**
 * Pull the text out by walking the output blocks, not by indexing into them:
 * a web-search turn puts tool calls in the same array as the message.
 */
function textOf(data: any): string {
  // Even valid-looking JSON must not be accepted from a truncated response.
  if (data.status === 'incomplete') {
    const reason = data.incomplete_details?.reason === 'max_output_tokens'
      ? 'max_output_tokens' : 'other';
    throw new Error(`OpenAI response incomplete (${reason})`);
  }
  if (data.status && data.status !== 'completed') throw new Error('OpenAI response not completed');
  if ((data.output ?? []).some((item: any) =>
    (item?.content ?? []).some((part: any) => part?.type === 'refusal'))) {
    throw new Error('OpenAI response refused');
  }
  if (typeof data.output_text === 'string' && data.output_text.length > 0) {
    return data.output_text;
  }

  const chunks: string[] = [];
  for (const item of data.output ?? []) {
    for (const part of item?.content ?? []) {
      if (part?.type === 'output_text' && typeof part.text === 'string') chunks.push(part.text);
    }
  }

  if (chunks.length === 0) throw new Error('OpenAI response carried no text');
  return chunks.join('\n');
}

export const openaiProvider: LLMProvider = {
  kind: 'openai',
  async parseSearch(query, locale) {
    return parseSearchIntent(await respond(setting<string>('OPENAI_TAGGING_MODEL'), searchIntentPrompt(query, locale), false, 2000, undefined, 'assistant'));
  },

  async tagPlace(facts: PlaceFacts): Promise<PlaceMarkup> {
    const text = await respond(
      setting<string>('OPENAI_TAGGING_MODEL'),
      buildTaggingPrompt(facts),
      false,
      setting('OPENAI_MAX_OUTPUT_TAGGING'),
      undefined,
      'tagging',
    );

    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    if (start === -1 || end === -1) throw new Error('OpenAI place markup is invalid');

    const parsed = JSON.parse(text.slice(start, end + 1));
    if (!Array.isArray(parsed?.tags) || !parsed.tags.length ||
        !parsed.tags.every((tag: unknown) => typeof tag === 'string' && tag.trim()) ||
        !Array.isArray(parsed.tagsRu) || parsed.tagsRu.length !== parsed.tags.length ||
        !parsed.tagsRu.every((tag: unknown) => typeof tag === 'string' && tag.trim()) ||
        typeof parsed.oneLiner !== 'string' || !parsed.oneLiner.trim()) {
      throw new Error('OpenAI place markup is invalid');
    }
    return {
      tags: Array.isArray(parsed?.tags) ? (parsed.tags as string[]) : [],
      tagsRu: Array.isArray(parsed?.tagsRu) ? (parsed.tagsRu as string[]) : [],
      oneLiner: typeof parsed?.oneLiner === 'string' ? parsed.oneLiner : '',
    };
  },

  async findCandidates(city, locale, usage, category, excludeNames, allowedTypes): Promise<Candidate[]> {
    // The cap includes reasoning, not just the 26-venue JSON. A live GPT-5
    // discovery exhausted 6000 tokens with 4800 spent on reasoning alone.
    return extractCandidates(
      await respond(setting<string>('OPENAI_MODEL'), buildDiscoveryPrompt(city, locale, category, excludeNames, allowedTypes, setting<string>('PROMPT_DISCOVERY')), true, setting('OPENAI_MAX_OUTPUT_DISCOVERY'), usage, 'discovery'),
    );
  },

  async rankTrip(input: RankInput, usage?: UsageSink): Promise<RankedTrip> {
    // No web search here: the candidates are already on the table, and search
    // would only let the model wander off the pool it was given.
    // Without a limit the prompt asks for seven places plus the wildcard.
    const limit = input.limit ?? 8;
    return extractRankedTrip(
      await respond(setting<string>('OPENAI_MODEL'), buildRankingPrompt(input, setting<string>('PROMPT_RANKING')), false, setting('OPENAI_MAX_OUTPUT_RANKING'), usage, 'ranking', rankingSchema(limit)),
      limit,
    );
  },
};

