/**
 * One spelling for venue names across sources: "Кофе на кухне", "Kofe Na Kukhne"
 * and "KOFE-NA-KUKHNE" all become "kofe na kukhne". Used to look a model's
 * venue name up in our own venue base without an external API.
 */
const CYRILLIC: Record<string, string> = {
  а: 'a', б: 'b', в: 'v', г: 'g', д: 'd', е: 'e', ё: 'e', ж: 'zh', з: 'z', и: 'i', й: 'y', к: 'k', л: 'l', м: 'm',
  н: 'n', о: 'o', п: 'p', р: 'r', с: 's', т: 't', у: 'u', ф: 'f', х: 'kh', ц: 'ts', ч: 'ch', ш: 'sh', щ: 'shch',
  ъ: '', ы: 'y', ь: '', э: 'e', ю: 'yu', я: 'ya',
};

export function nameKey(value: string): string {
  return value
    .toLowerCase()
    .replace(/[а-яё]/g, ch => CYRILLIC[ch] ?? ch)
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[&+]/g, ' and ')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

/** Words that say what a place is rather than which place it is. */
export const FILLER_WORDS = new Set([
  'bar', 'the', 'cafe', 'coffee', 'restaurant', 'restaurante', 'ristorante', 'cocktail', 'cocktails', 'club', 'and',
  'de', 'la', 'el', 'le', 'il', 'best', 'public', 'house', 'pub', 'kafe', 'restoran',
]);

/** Distinctive words of a name: what must be present for two names to be the same place. */
export function coreWords(key: string, extraFiller: readonly string[] = []): string[] {
  const filler = new Set([...FILLER_WORDS, ...extraFiller]);
  const words = key.split(' ').filter(Boolean);
  const core = words.filter(word => !filler.has(word));
  return core.length ? core : words;
}

/** Similarity of two keys from 0 to 1 (Dice coefficient over character bigrams). */
export function nameSimilarity(a: string, b: string): number {
  if (a === b) return 1;
  const grams = (s: string) => {
    const out = new Map<string, number>();
    for (let i = 0; i < s.length - 1; i += 1) out.set(s.slice(i, i + 2), (out.get(s.slice(i, i + 2)) ?? 0) + 1);
    return out;
  };
  const x = grams(a), y = grams(b);
  let shared = 0, total = 0;
  for (const [gram, count] of x) { shared += Math.min(count, y.get(gram) ?? 0); total += count; }
  for (const count of y.values()) total += count;
  return total ? (2 * shared) / total : 0;
}

