import { buildTaggingPrompt } from './taggingPrompt';
import { buildRankingPrompt, extractRankedTrip, type RankInput, type RankedTrip } from './prompt';

/**
 * Any OpenAI-compatible Chat Completions endpoint: a local Ollama, Groq,
 * OpenRouter, Gemini's compatibility endpoint. Configured entirely by env:
 *   LLM_CHAT_BASE_URL  e.g. http://127.0.0.1:11434/v1
 *   LLM_CHAT_MODEL     e.g. qwen2.5:7b-instruct
 *   LLM_CHAT_API_KEY   optional (Ollama needs none)
 *
 * It has no web search, so it cannot run discovery: with this provider the
 * candidate pool must come from the venue base (see `candidatesFor`).
 */

async function complete(prompt: string, maxTokens: number, usage?: UsageSink, step = 'call'): Promise<string> {
  const base = process.env.LLM_CHAT_BASE_URL;
  const model = process.env.LLM_CHAT_MODEL;
  if (!base || !model) throw new Error('LLM_CHAT_BASE_URL and LLM_CHAT_MODEL must be set');
  const res = await fetch(`${base.replace(/\/$/, '')}/chat/completions`, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      ...(process.env.LLM_CHAT_API_KEY ? { authorization: `Bearer ${process.env.LLM_CHAT_API_KEY}` } : {}),
    },
    body: JSON.stringify({
      model,
      messages: [
        { role: 'system', content: 'You answer with one JSON object only, no prose and no code fences.' },
        { role: 'user', content: prompt },
      ],
      max_tokens: maxTokens,
      temperature: 0.3,
      response_format: { type: 'json_object' },
    }),
    signal: AbortSignal.timeout(setting<number>('LLM_REQUEST_TIMEOUT_MS')),
  });
  if (!res.ok) throw new Error(`Chat LLM request failed: ${res.status}`);
  const data: any = await res.json();
  usage?.add(step, { input: data.usage?.prompt_tokens ?? 0, output: data.usage?.completion_tokens ?? 0 });
  const text = data.choices?.[0]?.message?.content;
  if (typeof text !== 'string' || !text.trim()) throw new Error('Chat LLM response carried no text');
  return text;
}

function jsonOf(text: string): any {
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('Chat LLM response is not JSON');
  return JSON.parse(text.slice(start, end + 1));
}

export const chatProvider: LLMProvider = {
  kind: 'chat',

  async parseSearch(query, locale) {
    return parseSearchIntent(await complete(searchIntentPrompt(query, locale), 1000, undefined, 'assistant'));
  },

  async tagPlace(facts: PlaceFacts): Promise<PlaceMarkup> {
    const parsed = jsonOf(await complete(buildTaggingPrompt(facts), setting('OPENAI_MAX_OUTPUT_TAGGING'), undefined, 'tagging'));
    const tags = Array.isArray(parsed?.tags) ? parsed.tags.filter((t: unknown) => typeof t === 'string' && t.trim()) : [];
    const tagsRu = Array.isArray(parsed?.tagsRu) ? parsed.tagsRu.filter((t: unknown) => typeof t === 'string' && t.trim()) : [];
    if (!tags.length || typeof parsed?.oneLiner !== 'string') throw new Error('Chat LLM place markup is invalid');
    // Small local models sometimes drop a translation; never show a mismatched pair.
    return { tags, tagsRu: tagsRu.length === tags.length ? tagsRu : tags, oneLiner: parsed.oneLiner };
  },

  async findCandidates() {
    throw new Error('DISCOVERY_NEEDS_VENUE_BASE');
  },

  async rankTrip(input: RankInput, usage?: UsageSink): Promise<RankedTrip> {
    const limit = input.limit ?? 8;
    return extractRankedTrip(
      await complete(buildRankingPrompt(input, setting<string>('PROMPT_RANKING')), setting('OPENAI_MAX_OUTPUT_RANKING'), usage, 'ranking'),
      limit,
    );
  },
};

