import type { PlaceFacts } from './provider';
import { outdoorTaggingContext } from './outdoorContext';

/** Exact tagging instructions used before 20fb4a1, shared by both providers. */
export function buildTaggingPrompt(facts: PlaceFacts): string {
  return `Describe this venue with 5–7 tags that can identify a similar place in ANOTHER city.

A tag describes transferable qualities: venue format, who goes there, service style, room size, noise level, price register, or ritual — "cocktails without a menu", "counter by the open kitchen", "no bookings", "local chefs go there", "open late".
DO NOT describe visual or interior details: signs, lanterns, wall colour, or furniture. They do not transfer and do not describe taste.
DO NOT use vague ratings such as "atmospheric", "cosy", or "delicious".${outdoorTaggingContext(facts.types, facts.primaryType) ? "\n" + outdoorTaggingContext(facts.types, facts.primaryType) : ""}
${facts.vocabulary?.length ? `Reuse these established phrases when they fit: ${facts.vocabulary.join(', ')}. Invent a new phrase only when none fit.` : ''}

Also write one sentence saying what the venue is; it will be used to find analogues.

Venue: ${facts.name}, ${[facts.area, facts.city].filter(Boolean).join(', ')}
Types: ${facts.types?.join(', ') ?? '—'}
Price level: ${facts.priceLevel ?? '—'}
Reviews: ${(facts.reviews ?? []).slice(0, 5).join(' | ') || '—'}

Write canonical tags in English, then the same tags in Russian in the same order.

OUTPUT JSON ONLY: {"tags":["…"],"tagsRu":["…"],"oneLiner":"…"}`;
}
