export const probePlace = defineOperation<{ query: string; city?: string }, unknown>(
  'admin.places.probe',
  async (ctx, { query, city }) => {
    await requireSuperAdmin(ctx.userId);
    const timed = async <T>(work: () => Promise<T>) => {
      const started = Date.now();
      try { return { ok: true as const, value: await work(), ms: Date.now() - started }; }
      catch (error) { return { ok: false as const, error: error instanceof Error ? error.message : String(error), ms: Date.now() - started }; }
