// One-off backfill for the local base: chainKey + chain flags, same rules as server/venuesImport.ts.
const { MongoClient } = require('C:/vdev/.meteor/packages/npm-mongo/6.16.2/npm/node_modules/mongodb');
const FILLER = new Set(['bar', 'the', 'cafe', 'coffee', 'restaurant', 'restaurante', 'ristorante', 'cocktail', 'cocktails',
  'club', 'and', 'de', 'la', 'el', 'le', 'il', 'best', 'public', 'house', 'pub', 'kafe', 'restoran']);
const core = key => { const w = key.split(' ').filter(Boolean); const c = w.filter(x => !FILLER.has(x)); return c.length ? c : w; };
(async () => {
  const c = await MongoClient.connect('mongodb://127.0.0.1:3201/?directConnection=true');
  const v = c.db('meteor').collection('venues');
  let batch = [], n = 0;
  for await (const d of v.find({}, { projection: { nameKey: 1 } })) {
    batch.push({ updateOne: { filter: { _id: d._id }, update: { $set: { chainKey: core(d.nameKey || '').slice(0, 2).join(' ') } } } });
    if (batch.length === 5000) { await v.bulkWrite(batch, { ordered: false }); n += batch.length; batch = []; }
  }
  if (batch.length) { await v.bulkWrite(batch, { ordered: false }); n += batch.length; }
  console.log('chainKey set', n);
  const chains = await v.aggregate([
    { $match: { candidate: true, chainKey: { $ne: '' } } },
    { $group: { _id: { city: '$city', chainKey: '$chainKey' }, n: { $sum: 1 } } },
    { $match: { n: { $gte: 3 } } },
  ], { allowDiskUse: true }).toArray();
  await v.updateMany({}, { $set: { chain: false } });
  const ops = chains.map(({ _id }) => ({ updateMany: { filter: { city: _id.city, chainKey: _id.chainKey }, update: { $set: { chain: true } } } }));
  for (let i = 0; i < ops.length; i += 2000) await v.bulkWrite(ops.slice(i, i + 2000), { ordered: false });
  console.log('chains', chains.length, 'venues flagged', await v.countDocuments({ chain: true }));
  console.log('London sample', (await v.find({ city: 'London', chain: true }).limit(10).project({ name: 1, _id: 0 }).toArray()).map(x => x.name).join(' | '));
  console.log('cityCandidates cleared', (await c.db('meteor').collection('cityCandidates').deleteMany({})).deletedCount);
  await c.close();
})();

