export function extractCandidates(text: string): Candidate[] {
  const parsed = parseJson(text);
  if (!Array.isArray(parsed?.places)) throw new Error('Discovery response has no places[]');
  const places = (parsed.places as unknown[]).map(candidateOf).filter((item: Candidate | null): item is Candidate => Boolean(item)).slice(0, 26);
