export function extractRankedTrip(text: string, limit = 8): RankedTrip {
  const parsed = parseJson(text);
  if (!Array.isArray(parsed?.places)) throw new Error('Ranking response has no places[]');
  const places = (parsed.places as unknown[]).map(tripPlaceOf).filter((item: RawTripPlace | null): item is RawTripPlace => Boolean(item)).slice(0, limit);
