import { setting } from '/server/runtimeSettings';
import type { LLMProvider, PlaceFacts, PlaceMarkup, UsageSink } from './provider';
import { searchIntentPrompt } from './searchIntentPrompt';
import { parseSearchIntent } from '/imports/domain/searchIntent';
import { buildTaggingPrompt } from './taggingPrompt';
import { buildRankingPrompt, extractRankedTrip, type RankInput, type RankedTrip } from './prompt';

/**
 * Any OpenAI-compatible Chat Completions endpoint: a local Ollama, Groq,
 * OpenRouter, Gemini's compatibility endpoint. Configured entirely by env:
 *   LLM_CHAT_BASE_URL  e.g. http://127.0.0.1:11434/v1
 *   LLM_CHAT_MODEL     e.g. qwen2.5:7b-instruct
 *   LLM_CHAT_API_KEY   optional (local Ollama needs none)
 * Place tags may use another provider, so the two free daily limits add up:
 *   LLM_CHAT_TAGGING_BASE_URL / _MODEL / _API_KEY  each falls back to the above
 * Free tiers run out mid-day, so further endpoints can back the main one up:
 *   LLM_CHAT_FALLBACKS  "baseUrl|model|ENV_VAR_WITH_KEY; ..." tried in order on any failure
 *
 * It has no web search, so it cannot run discovery: with this provider the
 * candidate pool must come from the venue base (see `candidatesFor`).
 */

type Role = 'main' | 'tagging';

function endpoint(role: Role) {
  const env = process.env;
  const pick = (name: string) => (role === 'tagging' ? env[`LLM_CHAT_TAGGING_${name}`] : undefined) || env[`LLM_CHAT_${name}`];
  return { base: pick('BASE_URL'), model: pick('MODEL'), key: pick('API_KEY') };
}

function fallbacks() {
  return (process.env.LLM_CHAT_FALLBACKS ?? '').split(';').map(item => item.trim()).filter(Boolean).map(item => {
    const [base, model, keyVar] = item.split('|').map(part => part.trim());
    return { base, model, key: keyVar ? process.env[keyVar] : undefined };
  });
}

async function complete(prompt: string, maxTokens: number, usage?: UsageSink, step = 'call', role: Role = 'main'): Promise<string> {
  const chain = [endpoint(role), ...fallbacks()];
  let failure: unknown;
  for (const target of chain) {
    try {
      return await completeAt(target, prompt, maxTokens, usage, step);
    } catch (error) {
      failure = error;
    }
  }
  throw failure;
}

async function completeAt(
  { base, model, key }: { base?: string; model?: string; key?: string },
  prompt: string, maxTokens: number, usage: UsageSink | undefined, step: string,
): Promise<string> {
  if (!base || !model) throw new Error('LLM_CHAT_BASE_URL and LLM_CHAT_MODEL must be set');
  const res = await fetch(`${base.replace(/\/$/, '')}/chat/completions`, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      // Some gateways reject requests without a product User-Agent.
      'user-agent': 'verger/1.0',
      ...(key ? { authorization: `Bearer ${key}` } : {}),
    },
    body: JSON.stringify({
      model,
      messages: [
        { role: 'system', content: 'You answer with one JSON object only, no prose and no code fences.' },
        { role: 'user', content: prompt },
      ],
      max_tokens: maxTokens,
      temperature: 0.3,
      response_format: { type: 'json_object' },
    }),
    signal: AbortSignal.timeout(setting<number>('LLM_REQUEST_TIMEOUT_MS')),
  });
  if (!res.ok) throw new Error(`Chat LLM request failed: ${res.status}`);
  const data: any = await res.json();
  usage?.add(step, { input: data.usage?.prompt_tokens ?? 0, output: data.usage?.completion_tokens ?? 0 });
  const text = data.choices?.[0]?.message?.content;
  if (typeof text !== 'string' || !text.trim()) throw new Error('Chat LLM response carried no text');
  return text;
}

/**
 * The open venue base has no neighbourhoods, and the ranking parser drops a
 * pick without one. When the model leaves "a" empty, the city stands in.
 */
function withAreas(text: string, city: string): string {
  try {
    const parsed = jsonOf(text);
    if (!Array.isArray(parsed?.places)) return text;
    const fallback = city.split(',')[0].trim();
    for (const place of parsed.places) {
      if (place && typeof place === 'object' && !(typeof place.a === 'string' && place.a.trim())) place.a = fallback;
    }
    return JSON.stringify(parsed);
  } catch {
    return text;
  }
}

/** Free models drift into English halfway through a list; the prompt's own rule is not enough. */
function languageReminder(locale?: string): string {
  return locale === 'en' ? '' : '

REMINDER: every "w" and "o" value MUST be written in Russian. Venue names stay as they are.';
}

function jsonOf(text: string): any {
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('Chat LLM response is not JSON');
  return JSON.parse(text.slice(start, end + 1));
}

export const chatProvider: LLMProvider = {
  kind: 'chat',

  async parseSearch(query, locale) {
    return parseSearchIntent(await complete(searchIntentPrompt(query, locale), 1000, undefined, 'assistant'));
  },

  async tagPlace(facts: PlaceFacts): Promise<PlaceMarkup> {
    const parsed = jsonOf(await complete(buildTaggingPrompt(facts), setting('OPENAI_MAX_OUTPUT_TAGGING'), undefined, 'tagging', 'tagging'));
    const tags = Array.isArray(parsed?.tags) ? parsed.tags.filter((t: unknown) => typeof t === 'string' && t.trim()) : [];
    const tagsRu = Array.isArray(parsed?.tagsRu) ? parsed.tagsRu.filter((t: unknown) => typeof t === 'string' && t.trim()) : [];
    if (!tags.length || typeof parsed?.oneLiner !== 'string') throw new Error('Chat LLM place markup is invalid');
    // Small local models sometimes drop a translation; never show a mismatched pair.
    return { tags, tagsRu: tagsRu.length === tags.length ? tagsRu : tags, oneLiner: parsed.oneLiner };
  },

  async findCandidates() {
    throw new Error('DISCOVERY_NEEDS_VENUE_BASE');
  },

  /**
   * Free models stop at 5–6 picks however many are asked for, so the batch is
   * collected in rounds of up to 7, each excluding what is already chosen.
   */
  async rankTrip(input: RankInput, usage?: UsageSink): Promise<RankedTrip> {
    const limit = input.limit ?? 8;
    const places: RankedTrip['places'] = [];
    let rejected: RankedTrip['rejected'] = [];
    const taken = () => places.map(place => place.n);
    for (let round = 0; round < 4 && places.length < limit; round += 1) {
      const want = Math.min(7, limit - places.length);
      const text = await complete(buildRankingPrompt({
        ...input,
        limit: want,
        excludeNames: [...(input.excludeNames ?? []), ...taken()],
      }, setting<string>('PROMPT_RANKING')) + languageReminder(input.locale), setting('OPENAI_MAX_OUTPUT_RANKING'), usage, 'ranking');
      let result: RankedTrip;
      try {
        result = extractRankedTrip(withAreas(text, input.city), want);
      } catch (error) {
        // A later round with nothing left to add must not discard earlier picks.
        if (places.length) break;
        throw error;
      }
      const seen = new Set(taken().map(name => name.toLowerCase()));
      const fresh = result.places.filter(place => !seen.has(place.n.toLowerCase()))
        // Only one experimental pick per collection.
        .map(place => (place.wild && places.some(p => p.wild) ? { ...place, wild: false } : place));
      if (!fresh.length) break;
      places.push(...fresh);
      if (!rejected.length) rejected = result.rejected;
    }
    return { places: places.slice(0, limit), rejected };
  },
};

