// places.search / places.cities: language and the trip-city bias. No Meteor, no API keys.
// Run: node --test scripts/places-search.test.mjs
import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { runInNewContext } from 'node:vm';
import { test } from 'node:test';
import assert from 'node:assert/strict';

const ts = createRequire(import.meta.url)('../app/node_modules/typescript');
function load(path, deps = {}, context = {}) {
  const exports = {};
  const source = readFileSync(new URL('../app/' + path, import.meta.url), 'utf8');
  const code = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 } }).outputText;
  runInNewContext(code, { exports, console, ...context, require(id) { assert.ok(id in deps, id); return deps[id]; } });
  return exports;
}
const venueTypes = load('imports/domain/venueTypes.ts');
const placeSelection = load('imports/domain/placeSelection.ts');

function fixture({ details } = {}) {
  let now = Date.UTC(2026, 0, 1);
  class Clock extends Date { static now() { return now; } }
  const searches = [], citySearches = [], lookups = [];
  const provider = {
    async search(query, opts) { searches.push({ query, opts }); return []; },
    async searchCities(query, sessionToken, languageCode) { citySearches.push({ query, sessionToken, languageCode }); return []; },
    async details(placeId) {
      lookups.push(placeId);
      return details ? details(placeId) : { placeId, name: 'City', city: 'City', lat: 21.03, lng: 105.85 };
    },
  };
  const ops = load('imports/api/operations/places.ts', {
    '../registry': { defineOperation: (_name, handler) => handler },
    '../providers': { getPlacesProvider: () => provider, getLLMProvider: () => { throw new Error('no model here'); } },
    '../collections': { PlacesCollection: {} },
    '/imports/domain/weights': { tagFrequencyOf: () => ({}) },
    '/imports/domain/categories': { categoryOf: () => 'other' },
    '/imports/domain/placeSelection': placeSelection,
    '/imports/domain/venueTypes': venueTypes,
  }, { Date: Clock, setTimeout, clearTimeout });
  const search = (args) => ops.searchPlaces({ userId: 'u1' }, { query: 'noto', ...args });
  return { search, cities: (args) => ops.searchCities({ userId: 'u1' }, { query: 'Par', ...args }), searches, citySearches, lookups, wait: (ms) => { now += ms; } };
}

test('search receives the traveller language and the centre of the trip city', async () => {
  const f = fixture();
  await f.search({ sessionToken: 'session-1', locale: 'ru', cityPlaceId: 'city-hanoi' });
  assert.equal(f.searches.length, 1);
  const { query, opts } = f.searches[0];
  assert.equal(query, 'noto');
  assert.equal(opts.sessionToken, 'session-1');
  assert.equal(opts.languageCode, 'ru');
  assert.equal(JSON.stringify(opts.near), JSON.stringify({ lat: 21.03, lng: 105.85 }));
  assert.deepEqual(f.lookups, ['city-hanoi']);
});

test('without a city or with an unknown language the search is as before', async () => {
  const f = fixture();
  await f.search({ locale: 'de' });
  await f.search({ cityPlaceId: null, locale: 'en' });
