import { OpenCitiesCollection, VenuesCollection, type OpenCity } from '../collections';
import { nameKey, nameSimilarity } from '/imports/domain/nameKey';
import { ratedPlacesPage, type RatedPlace } from './googleProvider';
import { reserveProviderRequest } from '../providerBudget';

/**
 * Google ratings on top of the open venue base, only for cities people search.
 *
 * One Text Search per city and venue kind returns Google's most visible places
 * with rating and review count; a quiet cafe with five reviews never appears,
 * so nothing is paid for it. Google allows ratings only as a cache: they are
 * ignored after RATING_TTL_DAYS and the query reruns on the next search of the
 * city. Only `googlePlaceId` is kept for good, as Google's terms allow.
 */
export const RATING_TTL_DAYS = 30;
const PAGES_PER_QUERY = 3;
const MATCH_METRES = 150;
const MIN_NAME_SIMILARITY = 0.6;

const QUERY_BY_TYPE: Record<string, string> = {
  cocktail_bar: 'cocktail bars', wine_bar: 'wine bars', pub: 'pubs', bar: 'bars', beer_garden: 'beer gardens',
  sports_bar: 'bars', night_club: 'nightclubs', cafe: 'cafes', coffee_shop: 'coffee shops', tea_house: 'cafes',
  bakery: 'bakeries', restaurant: 'restaurants', park: 'parks', garden: 'gardens', botanical_garden: 'gardens',
};

export function ratingQueries(primaryTypes: string[]): string[] {
  return [...new Set(primaryTypes.map(type => QUERY_BY_TYPE[type] ?? (type.endsWith('_restaurant') ? 'restaurants' : undefined))
    .filter((query): query is string => Boolean(query)))];
}

export const isFresh = (at: Date | undefined, now = Date.now()) =>
  Boolean(at) && now - at!.getTime() < RATING_TTL_DAYS * 86_400_000;

function metres(a: { lat: number; lng: number }, b: { lat: number; lng: number }) {
  const rad = Math.PI / 180;
  const dLat = (b.lat - a.lat) * rad, dLng = (b.lng - a.lng) * rad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLng / 2) ** 2;
  return 12_742_000 * Math.asin(Math.sqrt(h));
}

/** Attach one Google result to the venue it is: same name, a few doors at most. */
async function attach(city: OpenCity, place: RatedPlace, now: Date): Promise<boolean> {
  if (!place.id || !Number.isFinite(place.lat) || !Number.isFinite(place.lng)) return false;
  const d = 0.002; // ~200 m box, refined by distance below
  const nearby = await VenuesCollection.find({
    city: city.city, lat: { $gte: place.lat - d, $lte: place.lat + d }, lng: { $gte: place.lng - d * 2, $lte: place.lng + d * 2 },
  }, { fields: { venueId: 1, nameKey: 1, lat: 1, lng: 1 }, limit: 200 }).fetchAsync();
  const wanted = nameKey(place.name);
  const best = nearby
    .map(venue => ({ venue, score: nameSimilarity(wanted, venue.nameKey), far: metres(place, venue) }))
    .filter(item => item.far <= MATCH_METRES && item.score >= MIN_NAME_SIMILARITY)
    .sort((a, b) => b.score - a.score || a.far - b.far)[0];
  if (!best) return false;
  await VenuesCollection.updateAsync({ venueId: best.venue.venueId }, {
    $set: {
      googlePlaceId: place.id,
      ...(place.rating !== undefined ? { rating: place.rating, ratingCount: place.ratingCount ?? 0, ratingAt: now } : {}),
    },
  });
  return true;
}

/**
 * Refresh Google ratings for the kinds of venues a search needs. Does nothing
 * without GOOGLE_PLACES_KEY or when this city's query ran within the TTL.
 * Failures are swallowed: ratings improve a collection, they never block one.
 */
export async function refreshCityRatings(cityName: string, primaryTypes: string[]): Promise<{ requests: number; matched: number }> {
  const result = { requests: 0, matched: 0 };
  if (!process.env.GOOGLE_PLACES_KEY) return result;
  const city = await OpenCitiesCollection.findOneAsync({ city: cityName });
  if (!city) return result;
  const now = new Date();
  for (const query of ratingQueries(primaryTypes)) {
    if (isFresh(city.ratingsRefreshedAt?.[query], now.getTime())) continue;
    try {
      let token: string | undefined;
      for (let page = 0; page < PAGES_PER_QUERY; page += 1) {
        await reserveProviderRequest('places');
        result.requests += 1;
        const { places, nextPageToken } = await ratedPlacesPage(`${query} in ${city.label}`, city, token);
        for (const place of places) if (await attach(city, place, now)) result.matched += 1;
        if (!nextPageToken) break;
        token = nextPageToken;
      }
      await OpenCitiesCollection.updateAsync({ placeId: city.placeId }, { $set: { [`ratingsRefreshedAt.${query}`]: now } });
    } catch (error) {
      console.warn(`[ratings] ${city.city} "${query}" failed: ${error instanceof Error ? error.message : error}`);
    }
  }
  return result;
}

/** "рейтинг 4.6, 320 отзывов" for the ranker, only while Google allows keeping it. */
export function ratingFacts(venue: { rating?: number; ratingCount?: number; ratingAt?: Date }): string | undefined {
  if (venue.rating === undefined || !isFresh(venue.ratingAt)) return undefined;
  return [`рейтинг ${venue.rating}`, venue.ratingCount ? `${venue.ratingCount} отзывов` : ''].filter(Boolean).join(', ');
}

