// Google ratings over the open venue base. No Meteor, no network: Google is a stub.
// Run: node --test scripts/google-ratings.test.mjs
import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { runInNewContext } from 'node:vm';
import { test } from 'node:test';
import assert from 'node:assert/strict';

const ts = createRequire(import.meta.url)('../app/node_modules/typescript');
function load(path, deps = {}, context = {}) {
  const exports = {};
  const source = readFileSync(new URL('../app/' + path, import.meta.url), 'utf8');
  const code = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 } }).outputText;
  runInNewContext(code, { exports, console, ...context, require(id) { assert.ok(id in deps, id); return deps[id]; } });
  return exports;
}
const names = load('imports/domain/nameKey.ts');

function matches(doc, query) {
  return Object.entries(query).every(([key, cond]) => {
    const value = doc[key];
    if (cond && typeof cond === 'object' && !(cond instanceof Date)) {
      return (cond.$gte === undefined || value >= cond.$gte) && (cond.$lte === undefined || value <= cond.$lte);
    }
    return value === cond;
  });
}
function collection(docs) {
  return {
    docs,
    find: (query, opts = {}) => ({ fetchAsync: async () => docs.filter(d => matches(d, query)).slice(0, opts.limit ?? Infinity) }),
    findOneAsync: async query => docs.find(d => matches(d, query)),
    updateAsync: async (query, update) => {
      for (const doc of docs.filter(d => matches(d, query))) {
        for (const [key, value] of Object.entries(update.$set)) {
          const [head, tail] = key.split('.');
          if (tail) doc[head] = { ...(doc[head] ?? {}), [tail]: value }; else doc[key] = value;
        }
      }
    },
  };
}

function fixture({ key = 'test-only', pages } = {}) {
  const venues = collection([
    { venueId: 'v1', city: 'London', nameKey: names.nameKey('Satan\'s Whiskers'), lat: 51.5272, lng: -0.0577 },
    { venueId: 'v2', city: 'London', nameKey: names.nameKey('Connaught Bar'), lat: 51.5101, lng: -0.1497 },
  ]);
  const cities = collection([{ placeId: 'city_london', city: 'London', label: 'London, United Kingdom', lat: 51.51, lng: -0.13 }]);
  const queries = [];
  const google = {
    async ratedPlacesPage(query, _center, token) {
      queries.push({ query, token });
      return (pages ?? [{ places: [
        { id: 'g-satans', name: "Satan's Whiskers", lat: 51.5273, lng: -0.0578, rating: 4.7, ratingCount: 1500 },
        // Same name two kilometres away is somebody else.
        { id: 'g-far', name: 'Connaught Bar', lat: 51.528, lng: -0.12, rating: 3.1, ratingCount: 12 },
      ] }])[token ? Number(token) : 0];
    },
  };
  const ratings = load('imports/api/places/googleRatings.ts', {
    '../collections': { VenuesCollection: venues, OpenCitiesCollection: cities },
    '/imports/domain/nameKey': names,
    './googleProvider': google,
    '../providerBudget': { reserveProviderRequest: async () => {} },
  }, { process: { env: key ? { GOOGLE_PLACES_KEY: key } : {} }, Date });
  return { ratings, venues, cities, queries };
}

test('without a Google key nothing is requested and nothing changes', async () => {
  const f = fixture({ key: null });
  assert.deepEqual({ ...(await f.ratings.refreshCityRatings('London', ['cocktail_bar'])) }, { requests: 0, matched: 0 });
  assert.equal(f.queries.length, 0);
});

test('one query per venue kind, matched to the venue by name and distance only', async () => {
  const f = fixture();
  const result = await f.ratings.refreshCityRatings('London', ['cocktail_bar', 'speakeasy', 'wine_bar']);
  assert.deepEqual(f.queries.map(q => q.query), ['cocktail bars in London, United Kingdom', 'wine bars in London, United Kingdom']);
  assert.equal(result.matched, 2); // Satan's Whiskers matched once per query; the far Connaught never
  const satans = f.venues.docs[0], connaught = f.venues.docs[1];
  assert.equal(satans.googlePlaceId, 'g-satans');
  assert.equal(satans.rating, 4.7);
  assert.equal(connaught.googlePlaceId, undefined);
});

test('a city searched again within the cache period costs nothing', async () => {
  const f = fixture();
  await f.ratings.refreshCityRatings('London', ['cocktail_bar']);
  const again = await f.ratings.refreshCityRatings('London', ['cocktail_bar']);
  assert.equal(again.requests, 0);
  assert.equal(f.queries.length, 1);
});

test('pages are followed up to three, and a missing next page stops early', async () => {
  const page = (n, next) => ({ places: [], ...(next ? { nextPageToken: String(n) } : {}) });
  const f = fixture({ pages: [page(1, true), page(2, true), page(3, true), page(4, true)] });
  assert.equal((await f.ratings.refreshCityRatings('London', ['pub'])).requests, 3);
  const g = fixture({ pages: [page(1, false)] });
  assert.equal((await g.ratings.refreshCityRatings('London', ['pub'])).requests, 1);
});

test('a rating is shown to the ranker only while Google allows caching it', () => {
  const f = fixture();
  const day = 86_400_000;
  assert.equal(f.ratings.ratingFacts({ rating: 4.6, ratingCount: 320, ratingAt: new Date(Date.now() - 5 * day) }), 'рейтинг 4.6, 320 отзывов');
  assert.equal(f.ratings.ratingFacts({ rating: 4.6, ratingCount: 320, ratingAt: new Date(Date.now() - 31 * day) }), undefined);
  assert.equal(f.ratings.ratingFacts({}), undefined);
});

