Usage: coverage.py <top_list.csv> <map_name> <map_parquet_glob> [...more map_name glob pairs]
Writes <top_list>_coverage.csv with one column per map (matched name or empty) and prints totals.
"""
import csv, math, os, re, sys, unicodedata
import duckdb
from rapidfuzz import fuzz

CELL_LAT, CELL_LON = 0.002, 0.003  # ~200 m cells; neighbours cover the 150 m radius
MAX_METRES = 150
FILLER = {'bar', 'the', 'cafe', 'coffee', 'restaurant', 'restaurante', 'ristorante', 'cocktail', 'cocktails', 'club',
          'and', 'de', 'la', 'el', 'le', 'il', 'pub', 'trattoria', 'osteria', 'brasserie', 'bistro', 'hotel', 'at'}


def norm(s):
    s = unicodedata.normalize('NFKD', (s or '').lower()).encode('ascii', 'ignore').decode()
    s = s.replace('&', ' and ')
    return re.sub(r'[^a-z0-9]+', ' ', s).strip()


def core(s):
    words = norm(s).split()
    kept = [w for w in words if w not in FILLER]
    return ' '.join(kept or words)


def metres(lat1, lon1, lat2, lon2):
    r = math.pi / 180
    h = math.sin((lat2 - lat1) * r / 2) ** 2 + math.cos(lat1 * r) * math.cos(lat2 * r) * math.sin((lon2 - lon1) * r / 2) ** 2
    return 12_742_000 * math.asin(math.sqrt(h))


def same_place(want, got):
    a, b = core(want), core(got)
    if not a or not b:
        return False
    if a.replace(' ', '') == b.replace(' ', '') or a in b or b in a:
        return True
    return max(fuzz.token_set_ratio(a, b), fuzz.ratio(a, b)) >= 85


