            JOIN cells c ON floor(m.lat / {CELL_LAT})::BIGINT = c.cy AND floor(m.lon / {CELL_LON})::BIGINT = c.cx
        """).fetchall()
        for rank, name, lat, lon in pairs:
            _, want, wlat, wlng = items[rank]
            if rank in found[map_name] or metres(wlat, wlng, lat, lon) > MAX_METRES:
                continue
            if same_place(want, name):
                found[map_name][rank] = name
        print(f'{map_name}: {len(found[map_name])} of {len(items)} ({100 * len(found[map_name]) / len(items):.1f}%)')
    either = set().union(*[set(f) for f in found.values()])
    print(f'any map: {len(either)} of {len(items)} ({100 * len(either) / len(items):.1f}%)')
    out = top_path.replace('.csv', '_coverage.csv')
