"""AllThePlaces: keep bars, pubs, restaurants, cafes, clubs from the run archive into atp.parquet."""
import json, os, sys, zipfile
import duckdb

HERE = os.path.dirname(os.path.abspath(__file__))
KEEP = {'bar', 'pub', 'restaurant', 'cafe', 'nightclub', 'biergarten', 'fast_food'}


def main():
    sys.stdout.reconfigure(encoding='utf-8')
    rows = []
    with zipfile.ZipFile(os.path.join(HERE, 'atp_output.zip')) as archive:
        for info in archive.infolist():
            if not info.filename.endswith('.geojson'):
                continue
            try:
                data = json.loads(archive.read(info))
            except Exception:
                continue
            for feature in data.get('features', []):
                props = feature.get('properties') or {}
                amenity = props.get('amenity')
                geom = feature.get('geometry') or {}
                if amenity not in KEEP or geom.get('type') != 'Point' or not props.get('name'):
                    continue
                lon, lat = geom['coordinates'][:2]
                rows.append((props.get('ref') or feature.get('id') or '', props['name'], lat, lon, amenity,
                             props.get('brand') or '', props.get('@spider') or ''))
    con = duckdb.connect()
    con.execute('CREATE TABLE t (id VARCHAR, name VARCHAR, lat DOUBLE, lon DOUBLE, category VARCHAR, brand VARCHAR, spider VARCHAR)')
    con.executemany('INSERT INTO t VALUES (?, ?, ?, ?, ?, ?, ?)', rows)
    con.execute(f"COPY t TO '{os.path.join(HERE, 'atp.parquet').replace(os.sep, '/')}' (FORMAT parquet, COMPRESSION zstd)")
    print('atp venues', len(rows), dict(con.execute('SELECT category, count(*) FROM t GROUP BY 1').fetchall()))


if __name__ == '__main__':
    main()

