  if (type === "bakery") return "cafe";
  if (type === "club") return "bar";
  if (type === "garden") return "park";
  return type;
}

export const navigationLabels = {
  cafe: venueTypeLabels.cafe,
  restaurant: venueTypeLabels.restaurant,
  bar: { en: "Bars & clubs", ru: "Бары и клубы" },
  park: { en: "Nature", ru: "Природа" },
};

export function groupedVenueTypes(types: readonly VenueType[]): NavigationGroup[] {
  const present = new Set(types.map(navigationGroup));
  return navigationGroups.filter(group => present.has(group));
}

export function typesInNavigationGroup(group: NavigationGroup, types: readonly VenueType[]): VenueType[] {
  return types.filter(type => navigationGroup(type) === group);
}

