  restaurant: ['restaurant', 'steak_house', 'food_court', 'meal_takeaway', 'meal_delivery'], bakery: ['bakery'],
  park: ['park'], garden: ['garden', 'botanical_garden'],
};
const typeOf = p => {
  if (!p) return '';
  if (p.endsWith('_restaurant')) return 'restaurant';
  for (const [k, v] of Object.entries(defs)) if (v.includes(p)) return k;
  return '';
};
(async () => {
  const t = Date.now();
